{"command":"python3 - << 'PY'
import subprocess, os, shutil, pathlib
EXE="/workspace/executable"
def setup(base, gitmode):
    shutil.rmtree(base, ignore_errors=True)
    pathlib.Path(base+"/sub/pkg").mkdir(parents=True)
    pathlib.Path(base+"/sub/main.py").write_text("import pkg.a\n")
    pathlib.Path(base+"/sub/pkg/__init__.py").write_text("")
    pathlib.Path(base+"/sub/pkg/a.py").write_text("x=1\n")
    if gitmode=="fake_dir":
        pathlib.Path(base+"/.git").mkdir()
    elif gitmode=="fake_index":
        pathlib.Path(base+"/.git").mkdir(); pathlib.Path(base+"/.git/index").write_bytes(b"")
    elif gitmode=="fake_head":
        pathlib.Path(base+"/.git").mkdir(); pathlib.Path(base+"/.git/HEAD").write_text("ref: refs/heads/main\n")
    elif gitmode=="init":
        subprocess.run(["git","init","-q"],cwd=base)
    elif gitmode=="init_index_empty":
        subprocess.run(["git","init","-q"],cwd=base); pathlib.Path(base+"/.git/index").write_bytes(b"")
    elif gitmode=="git_file":
        pathlib.Path(base+"/.git").write_text("gitdir: /tmp/elsewhere\n")

def run(base):
    p=subprocess.run([EXE,"tree","main.py","--json"],capture_output=True,text=True,cwd=base+"/sub")
    print(p.stdout.strip(), "exit",p.returncode)
for m in ["none","fake_dir","fake_index","fake_head","init","init_index_empty","git_file"]:
    print("\nmode",m)
    setup("/tmp/fake1",m)
    run("/tmp/fake1")
PY"}

