cat > internal/globutil/glob.go <<'EOF'
package globutil

import (
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var ErrBadPattern = errors.New("syntax error in pattern")

// ValidatePattern reports whether pattern has valid glob syntax.
func ValidatePattern(pattern string) bool {
	_, err := expandBraces(pattern)
	if err != nil {
		return false
	}
	// Validate character classes and escapes in every segment.
	for _, p := range mustExpand(pattern) {
		for _, seg := range splitPattern(p) {
			if _, err := parseSegment(seg); err != nil {
				return false
			}
		}
	}
	return true
}

func mustExpand(pattern string) []string {
	pats, _ := expandBraces(pattern)
	return pats
}

// Match matches name against a doublestar-style pattern, using '/' as separator.
func Match(pattern, name string) (bool, error) {
	pats, err := expandBraces(pattern)
	if err != nil {
		return false, err
	}
	for _, p := range pats {
		ok, err := matchOne(p, name)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}
	return false, nil
}

func matchOne(pattern, name string) (bool, error) {
	psegs := splitPattern(pattern)
	nsegs := splitPattern(name)
	// Validate all segments up front so bad classes are reported like path.Match.
	for _, s := range psegs {
		if _, err := parseSegment(s); err != nil {
			return false, err
		}
	}
	var rec func(pi, ni int) bool
	rec = func(pi, ni int) bool {
		for pi < len(psegs) {
			if psegs[pi] == "**" {
				// ** matches zero or more segments.
				if pi == len(psegs)-1 {
					return true
				}
				for skip := ni; skip <= len(nsegs); skip++ {
					if rec(pi+1, skip) {
						return true
					}
				}
				return false
			}
			if ni >= len(nsegs) {
				return false
			}
			if !segmentMatch(psegs[pi], nsegs[ni]) {
				return false
			}
			pi++
			ni++
		}
		return ni == len(nsegs)
	}
	return rec(0, 0), nil
}

func splitPattern(p string) []string {
	if p == "" {
		return []string{""}
	}
	return strings.Split(p, "/")
}

// expandBraces expands {a,b} alternatives (possibly nested).
func expandBraces(pattern string) ([]string, error) {
	start := -1
	inClass := false
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
		case '{':
			start = i
			i = len(pattern)
		}
		if start >= 0 {
			break
		}
	}
	if start < 0 {
		// A stray closing brace is treated literally by doublestar.
		return []string{pattern}, nil
	}
	depth := 0
	end := -1
	inClass = false
	var commas []int
	for i := start; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				end = i
				i = len(pattern)
			}
		case ',':
			if depth == 1 {
				commas = append(commas, i)
			}
		}
		if end >= 0 {
			break
		}
	}
	if end < 0 {
		return nil, ErrBadPattern
	}
	if len(commas) == 0 {
		// No alternatives: treat braces literally, but continue looking after.
		rest, err := expandBraces(pattern[end+1:])
		if err != nil {
			return nil, err
		}
		out := make([]string, 0, len(rest))
		for _, r := range rest {
			out = append(out, pattern[:end+1]+r)
		}
		return out, nil
	}
	parts := []string{}
	prev := start + 1
	for _, c := range commas {
		parts = append(parts, pattern[prev:c])
		prev = c + 1
	}
	parts = append(parts, pattern[prev:end])
	var out []string
	for _, part := range parts {
		expanded, err := expandBraces(pattern[:start] + part + pattern[end+1:])
		if err != nil {
			return nil, err
		}
		out = append(out, expanded...)
	}
	return out, nil
}

type segToken struct {
	kind int // 0 literal rune, 1 star, 2 question, 3 class
	r    rune
	neg  bool
	set  map[rune]bool
	lohi [][2]rune
}

func parseSegment(seg string) ([]segToken, error) {
	var toks []segToken
	runes := []rune(seg)
	for i := 0; i < len(runes); i++ {
		c := runes[i]
		switch c {
		case '\\':
			i++
			if i >= len(runes) {
				return nil, ErrBadPattern
			}
			toks = append(toks, segToken{kind: 0, r: runes[i]})
		case '*':
			// Collapse runs of stars inside a segment.
			for i+1 < len(runes) && runes[i+1] == '*' {
				i++
			}
			toks = append(toks, segToken{kind: 1})
		case '?':
			toks = append(toks, segToken{kind: 2})
		case '[':
			tok := segToken{kind: 3, set: map[rune]bool{}}
			j := i + 1
			if j < len(runes) && (runes[j] == '^' || runes[j] == '!') {
				// Go path.Match only documents '^'; support both for shell-like globs only for '^'.
				// To stay close to path.Match, treat '!' literally unless it is '^'.
				if runes[j] == '^' {
					tok.neg = true
					j++
				}
			}
			if j >= len(runes) {
				return nil, ErrBadPattern
			}
			// A ']' as first class char is literal.
			first := true
			closed := false
			for ; j < len(runes); j++ {
				if runes[j] == ']' && !first {
					closed = true
					break
				}
				first = false
				var lo rune
				if runes[j] == '\\' {
					j++
					if j >= len(runes) {
						return nil, ErrBadPattern
					}
					lo = runes[j]
				} else {
					lo = runes[j]
				}
				// Range?
				if j+2 < len(runes) && runes[j+1] == '-' && runes[j+2] != ']' {
					hi := runes[j+2]
					k := j + 2
					if hi == '\\' {
						k++
						if k >= len(runes) {
							return nil, ErrBadPattern
						}
						hi = runes[k]
					}
					if lo > hi {
						return nil, ErrBadPattern
					}
					tok.lohi = append(tok.lohi, [2]rune{lo, hi})
					j = k
				} else {
					tok.set[lo] = true
				}
			}
			if !closed {
				return nil, ErrBadPattern
			}
			i = j
			toks = append(toks, tok)
		default:
			toks = append(toks, segToken{kind: 0, r: c})
		}
	}
	return toks, nil
}

func (t segToken) matchesRune(r rune) bool {
	in := t.set[r]
	if !in {
		for _, lh := range t.lohi {
			if r >= lh[0] && r <= lh[1] {
				in = true
				break
			}
		}
	}
	if t.neg {
		return !in
	}
	return in
}

func segmentMatch(pattern, name string) bool {
	toks, err := parseSegment(pattern)
	if err != nil {
		return false
	}
	rs := []rune(name)
	// DP wildcard match.
	type key struct{ ti, ri int }
	memo := map[key]bool{}
	seen := map[key]bool{}
	var rec func(ti, ri int) bool
	rec = func(ti, ri int) bool {
		k := key{ti, ri}
		if seen[k] {
			return memo[k]
		}
		seen[k] = true
		var out bool
		if ti == len(toks) {
			out = ri == len(rs)
		} else {
			t := toks[ti]
			switch t.kind {
			case 1:
				for skip := ri; skip <= len(rs); skip++ {
					if rec(ti+1, skip) {
						out = true
						break
					}
				}
			case 2:
				if ri < len(rs) {
					out = rec(ti+1, ri+1)
				}
			case 3:
				if ri < len(rs) && t.matchesRune(rs[ri]) {
					out = rec(ti+1, ri+1)
				}
			default:
				if ri < len(rs) && rs[ri] == t.r {
					out = rec(ti+1, ri+1)
				}
			}
		}
		memo[k] = out
		return out
	}
	return rec(0, 0)
}

func hasMeta(seg string) bool {
	return strings.ContainsAny(seg, "*?[{\\")
}

// Glob expands pattern against the filesystem. Returned paths keep the
// relative/absolute flavour of the input pattern.
func Glob(pattern string) ([]string, error) {
	pats, err := expandBraces(pattern)
	if err != nil {
		return nil, err
	}
	var all []string
	for _, p := range pats {
		for _, seg := range splitPattern(p) {
			if _, err := parseSegment(seg); err != nil {
				return nil, err
			}
		}
		matches, err := globOne(p)
		if err != nil {
			return nil, err
		}
		all = append(all, matches...)
	}
	return all, nil
}

func globOne(pattern string) ([]string, error) {
	abs := filepath.IsAbs(pattern)
	segs := splitPattern(pattern)
	// Remove leading empty segment for absolute paths.
	startIdx := 0
	rootFS := "."
	rootDisp := ""
	if abs {
		rootFS = string(os.PathSeparator)
		rootDisp = string(os.PathSeparator)
		if len(segs) > 0 && segs[0] == "" {
			startIdx = 1
		}
	}
	type state struct {
		fs   string
		disp string
	}
	var results []string
	// To guard symlinked dir loops during **, track visited (fs,idx) via recursion stack.
	var rec func(idx int, cur state, stack map[string]bool)
	rec = func(idx int, cur state, stack map[string]bool) {
		if idx == len(segs) {
			// cur must exist.
			p := cur.fs
			if p == "" {
				p = "."
			}
			if _, err := os.Lstat(p); err == nil {
				d := cur.disp
				if d == "" {
					d = "."
				}
				results = append(results, d)
			}
			return
		}
		seg := segs[idx]
		if seg == "**" {
			// Zero segments.
			rec(idx+1, cur, stack)
			// One or more: descend into entries.
			entries, err := readDirSorted(cur.fs)
			if err != nil {
				return
			}
			for _, e := range entries {
				childFS := joinFS(cur.fs, e.Name())
				childDisp := joinDisp(cur.disp, e.Name(), abs)
				// Consume one segment and stay on ** if directory.
				isDir := isDirEntry(childFS, e)
				if isDir {
					key := childFS + "|**"
					if stack[key] {
						continue
					}
					stack[key] = true
					rec(idx, state{childFS, childDisp}, stack)
					delete(stack, key)
				} else {
					// Files can be consumed by ** then advance via the zero-step at next level?
					// Emulate segment consumption: rec(idx+1) from the file path.
					// But idx+1 from a file will only succeed if no more segments.
					// Instead handle by treating file as terminal candidate for remainder:
					rec(idx+1, state{childFS, childDisp}, stack)
				}
			}
			return
		}
		if seg == "." {
			rec(idx+1, cur, stack)
			return
		}
		if seg == ".." {
			parentFS := filepath.Dir(cur.fs)
			parentDisp := dispDir(cur.disp, abs)
			rec(idx+1, state{parentFS, parentDisp}, stack)
			return
		}
		if !hasMeta(seg) {
			childFS := joinFS(cur.fs, seg)
			if _, err := os.Lstat(childFS); err != nil {
				return
			}
			rec(idx+1, state{childFS, joinDisp(cur.disp, seg, abs)}, stack)
			return
		}
		entries, err := readDirSorted(cur.fs)
		if err != nil {
			return
		}
		for _, e := range entries {
			if segmentMatch(seg, e.Name()) {
				childFS := joinFS(cur.fs, e.Name())
				rec(idx+1, state{childFS, joinDisp(cur.disp, e.Name(), abs)}, stack)
			}
		}
	}
	_ = startIdx
	if abs {
		rec(1, state{rootFS, rootDisp}, map[string]bool{})
	} else {
		// Empty pattern: split gives [""]; treat as no match path ""? os.Lstat("") fails.
		if pattern == "" {
			return nil, nil
		}
		rec(0, state{rootFS, rootDisp}, map[string]bool{})
	}
	return results, nil
}

func readDirSorted(dir string) ([]os.DirEntry, error) {
	if dir == "" {
		dir = "."
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	return entries, nil
}

func isDirEntry(path string, e os.DirEntry) bool {
	if e.IsDir() {
		return true
	}
	// Follow symlinks for ** traversal similar to walking behaviour.
	if e.Type()&os.ModeSymlink != 0 {
		if info, err := os.Stat(path); err == nil {
			return info.IsDir()
		}
	}
	return false
}

func joinFS(dir, name string) string {
	if dir == "" || dir == "." {
		return name
	}
	return filepath.Join(dir, name)
}

func joinDisp(disp, name string, abs bool) string {
	if abs {
		if disp == "/" {
			return "/" + name
		}
		return disp + "/" + name
	}
	if disp == "" {
		return name
	}
	return disp + "/" + name
}

func dispDir(disp string, abs bool) string {
	if abs {
		d := filepath.Dir(disp)
		return d
	}
	if disp == "" {
		return ".."
	}
	// Display parent for relative paths: use path cleaning on display string.
	if disp == "." {
		return ".."
	}
	idx := strings.LastIndex(disp, "/")
	if idx < 0 {
		return ".."
	}
	if idx == 0 {
		return "/"
	}
	return disp[:idx]
}
