package config

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"deptree/internal/check"
	"deptree/internal/globutil"
	"deptree/internal/js"
	"deptree/internal/python"
	"deptree/internal/rust"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Exclude       []string      `yaml:"exclude"`
	Only          []string      `yaml:"only"`
	UnwrapExports bool          `yaml:"unwrapExports"`
	Check         check.Config  `yaml:"check"`
	Js            js.Config     `yaml:"js"`
	Python        python.Config `yaml:"python"`
	Rust          rust.Config   `yaml:"rust"`
}

func defaults() Config {
	return Config{
		Js: js.Config{Workspaces: true, TsConfigPaths: true},
	}
}

type CliFlags struct {
	UnwrapExports                 bool
	UnwrapExportsChanged          bool
	JsWorkspaces                  bool
	JsWorkspacesChanged           bool
	JsTsConfigPaths               bool
	JsTsConfigPathsChanged        bool
	PythonExcludeConditional      bool
	PythonExcludeConditionalChanged bool
	Only                          []string
	Exclude                       []string
}

type Loaded struct {
	File    Config // as loaded from file (or defaults)
	Effective Config
	Path    string // effective path as given/default
	Dir     string // absolute dir of config file
	Exists  bool
}

func Load(path string, changed bool, cli CliFlags) (*Loaded, error) {
	effectivePath := path
	if effectivePath == "" {
		effectivePath = ".dep-tree.yml"
	}
	explicit := changed && path != ""
	fileCfg := defaults()
	exists := false
	absPath, _ := filepath.Abs(effectivePath)
	dir := filepath.Dir(absPath)
	data, err := os.ReadFile(effectivePath)
	if err != nil {
		if explicit || !errors.Is(err, os.ErrNotExist) {
			return nil, err
		}
		// Missing default config: proceed with defaults.
		// Dir should still be dir of the would-be config file (cwd).
	} else {
		exists = true
		dec := yaml.NewDecoder(bytes.NewReader(data))
		dec.KnownFields(true)
		if err := dec.Decode(&fileCfg); err != nil {
			return nil, fmt.Errorf("config file \"%s\" is not a valid yml file: %s", effectivePath, err)
		}
	}
	eff := fileCfg
	// Boolean resolution observed from the binary: when a flag is present on
	// the command line, the value from the config file wins; otherwise the
	// flag (default) value wins.
	eff.UnwrapExports = resolveBool(cli.UnwrapExports, cli.UnwrapExportsChanged, fileCfg.UnwrapExports)
	eff.Js.Workspaces = resolveBool(cli.JsWorkspaces, cli.JsWorkspacesChanged, fileCfg.Js.Workspaces)
	eff.Js.TsConfigPaths = resolveBool(cli.JsTsConfigPaths, cli.JsTsConfigPathsChanged, fileCfg.Js.TsConfigPaths)
	eff.Python.ExcludeConditionalImports = resolveBool(cli.PythonExcludeConditional, cli.PythonExcludeConditionalChanged, fileCfg.Python.ExcludeConditionalImports)

	// only/exclude: config entries are made absolute relative to the config
	// directory, cli entries relative to the working directory, then combined.
	cwd, _ := os.Getwd()
	eff.Exclude = nil
	for _, p := range fileCfg.Exclude {
		eff.Exclude = append(eff.Exclude, makeAbsPattern(dir, p))
	}
	for _, p := range cli.Exclude {
		eff.Exclude = append(eff.Exclude, makeAbsPattern(cwd, p))
	}
	eff.Only = nil
	for _, p := range fileCfg.Only {
		eff.Only = append(eff.Only, makeAbsPattern(dir, p))
	}
	for _, p := range cli.Only {
		eff.Only = append(eff.Only, makeAbsPattern(cwd, p))
	}
	for _, p := range eff.Exclude {
		if !globutil.ValidatePattern(p) {
			return nil, fmt.Errorf("exclude pattern '%s' is not correctly formatted", p)
		}
	}
	for _, p := range eff.Only {
		if !globutil.ValidatePattern(p) {
			return nil, fmt.Errorf("only pattern '%s' is not correctly formatted", p)
		}
	}
	return &Loaded{File: fileCfg, Effective: eff, Path: effectivePath, Dir: dir, Exists: exists}, nil
}

func resolveBool(flagVal bool, changed bool, cfgVal bool) bool {
	if changed {
		return cfgVal
	}
	return flagVal
}

func makeAbsPattern(base, p string) string {
	if filepath.IsAbs(p) {
		return filepath.Clean(p)
	}
	return filepath.Join(base, p)
}
