package graph

import (
	"hash/fnv"
	"os"
	"path/filepath"
	"strings"

	"deptree/internal/globutil"
	"deptree/internal/language"
)

type Node struct {
	AbsPath      string
	DisplayPath  string
	Group        string
	Loc          int
	Dependencies []string // absolute paths of loaded dependency nodes, parser order, deduped, no self
	Errors       []string
}

func (n *Node) ID() uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(n.AbsPath))
	return h.Sum32()
}

type Graph struct {
	Nodes []*Node // BFS load order
	ByAbs map[string]*Node
	Entrypoints []string
}

type Ignorer struct {
	Only    []string
	Exclude []string
}

func (ig *Ignorer) IsIgnored(absPath string) bool {
	if ig == nil {
		return false
	}
	for _, p := range ig.Exclude {
		if ok, _ := globutil.Match(p, absPath); ok {
			return true
		}
	}
	if len(ig.Only) > 0 {
		for _, p := range ig.Only {
			if ok, _ := globutil.Match(p, absPath); ok {
				return false
			}
		}
		return true
	}
	return false
}

type Progress interface {
	Start()
	Update(loaded, total int)
	Finish(loaded, total int)
}

type noopProgress struct{}
func (noopProgress) Start() {}
func (noopProgress) Update(int,int) {}
func (noopProgress) Finish(int,int) {}

// Load parses entrypoints breadth-first following dependencies.
func Load(entrypoints []string, parser language.Parser, ignorer *Ignorer, progress Progress) (*Graph, error) {
	if progress == nil {
		progress = noopProgress{}
	}
	progress.Start()
	g := &Graph{ByAbs: map[string]*Node{}, Entrypoints: append([]string(nil), entrypoints...)}
	seen := map[string]bool{}
	var queue []string
	for _, e := range entrypoints {
		e = filepath.Clean(e)
		if !seen[e] {
			seen[e] = true
			queue = append(queue, e)
		}
	}
	total := len(queue)
	loaded := 0
	type pending struct {
		node *Node
		rawDeps []string
	}
	var pend []*pending
	for i := 0; i < len(queue); i++ {
		abs := queue[i]
		if ignorer.IsIgnored(abs) {
			continue
		}
		pf, err := parser.ParseFile(abs)
		if err != nil {
			return nil, err
		}
		node := &Node{AbsPath: abs, DisplayPath: pf.DisplayPath, Group: pf.Group, Loc: pf.Loc, Errors: pf.Errors}
		g.Nodes = append(g.Nodes, node)
		g.ByAbs[abs] = node
		pend = append(pend, &pending{node: node, rawDeps: pf.Dependencies})
		loaded++
		for _, dep := range pf.Dependencies {
			dep = filepath.Clean(dep)
			if dep == abs {
				continue
			}
			if ignorer.IsIgnored(dep) {
				continue
			}
			if !seen[dep] {
				seen[dep] = true
				queue = append(queue, dep)
				total++
			}
		}
		progress.Update(loaded, total)
	}
	// Resolve adjacency to loaded nodes, dedupe preserve order, drop self.
	for _, p := range pend {
		dedup := map[string]bool{}
		for _, dep := range p.rawDeps {
			dep = filepath.Clean(dep)
			if dep == p.node.AbsPath || dedup[dep] {
				continue
			}
			if _, ok := g.ByAbs[dep]; !ok {
				continue
			}
			dedup[dep] = true
			p.node.Dependencies = append(p.node.Dependencies, dep)
		}
	}
	progress.Finish(loaded, total)
	return g, nil
}

func CountLoc(data []byte) int {
	return strings.Count(string(data), "\n")
}

func ReadFileLoc(abs string) ([]byte, int, error) {
	data, err := os.ReadFile(abs)
	if err != nil {
		return nil, 0, err
	}
	return data, CountLoc(data), nil
}

// CircularDependenciesForCheck finds cycles by trying, for each node in
// ascending FNV-id order, a shortest (BFS) cycle back to itself. Cycles with
// the same set of nodes are de-duplicated.
func (g *Graph) CircularDependenciesForCheck() [][]string {
	// Order nodes by ascending id.
	nodes := append([]*Node(nil), g.Nodes...)
	// insertion sort by ID (small helper to avoid importing sort with closures above)
	for i := 1; i < len(nodes); i++ {
		for j := i; j > 0 && nodes[j].ID() < nodes[j-1].ID(); j-- {
			nodes[j], nodes[j-1] = nodes[j-1], nodes[j]
		}
	}
	var cycles [][]string
	seenSets := map[string]bool{}
	for _, start := range nodes {
		cycle := g.shortestCycleThrough(start.AbsPath)
		if cycle == nil {
			continue
		}
		// Build set key of cycle nodes without repeated last.
		set := map[string]bool{}
		for _, a := range cycle[:len(cycle)-1] {
			set[a] = true
		}
		var keys []string
		for k := range set {
			keys = append(keys, k)
		}
		// sort keys
		for i := 1; i < len(keys); i++ {
			for j := i; j > 0 && keys[j] < keys[j-1]; j-- {
				keys[j], keys[j-1] = keys[j-1], keys[j]
			}
		}
		key := strings.Join(keys, "\x00")
		if seenSets[key] {
			continue
		}
		seenSets[key] = true
		var disp []string
		for _, a := range cycle {
			disp = append(disp, g.ByAbs[a].DisplayPath)
		}
		cycles = append(cycles, disp)
	}
	if cycles == nil {
		cycles = [][]string{}
	}
	return cycles
}

func (g *Graph) shortestCycleThrough(start string) []string {
	// BFS from start looking for an edge back to start.
	parent := map[string]string{}
	visited := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		node := g.ByAbs[cur]
		if node == nil {
			continue
		}
		for _, dep := range node.Dependencies {
			if dep == start {
				if cur == start {
					continue
				}
				// Reconstruct start..cur
				var rev []string
				for x := cur; ; x = parent[x] {
					rev = append(rev, x)
					if x == start {
						break
					}
				}
				// Reverse.
				var path []string
				for i := len(rev) - 1; i >= 0; i-- {
					path = append(path, rev[i])
				}
				path = append(path, start)
				return path
			}
			if !visited[dep] {
				visited[dep] = true
				parent[dep] = cur
				queue = append(queue, dep)
			}
		}
	}
	return nil
}
