// ascending FNV-id order, a shortest (BFS) cycle back to itself. Cycles with
// the same set of nodes are de-duplicated.
func (g *Graph) CircularDependenciesForCheck() [][]string {
	// Order nodes by ascending id.
	nodes := append([]*Node(nil), g.Nodes...)
	// insertion sort by ID (small helper to avoid importing sort with closures above)
	for i := 1; i < len(nodes); i++ {
		for j := i; j > 0 && nodes[j].ID() < nodes[j-1].ID(); j-- {
			nodes[j], nodes[j-1] = nodes[j-1], nodes[j]
		}
	}
	var cycles [][]string
	seenSets := map[string]bool{}
	for _, start := range nodes {
		cycle := g.shortestCycleThrough(start.AbsPath)
		if cycle == nil {
			continue
		}
		// Build set key of cycle nodes without repeated last.
		set := map[string]bool{}
		for _, a := range cycle[:len(cycle)-1] {
			set[a] = true
		}
		var keys []string
		for k := range set {
			keys = append(keys, k)
		}
		// sort keys
		for i := 1; i < len(keys); i++ {
			for j := i; j > 0 && keys[j] < keys[j-1]; j-- {
				keys[j], keys[j-1] = keys[j-1], keys[j]
			}
		}
		key := strings.Join(keys, "\x00")
		if seenSets[key] {
			continue
		}
		seenSets[key] = true
		var disp []string
		for _, a := range cycle {
			disp = append(disp, g.ByAbs[a].DisplayPath)
		}
		cycles = append(cycles, disp)
	}
