		cycles = [][]string{}
	}
	return cycles
}

func (g *Graph) shortestCycleThrough(start string) []string {
	// BFS from start looking for an edge back to start.
	parent := map[string]string{}
	visited := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		node := g.ByAbs[cur]
		if node == nil {
			continue
		}
		for _, dep := range node.Dependencies {
			if dep == start {
				if cur == start {
					continue
				}
				// Reconstruct start..cur
				var rev []string
				for x := cur; ; x = parent[x] {
					rev = append(rev, x)
					if x == start {
						break
					}
				}
				// Reverse.
				var path []string
				for i := len(rev) - 1; i >= 0; i-- {
					path = append(path, rev[i])
				}
				path = append(path, start)
				return path
			}
			if !visited[dep] {
				visited[dep] = true
				parent[dep] = cur
				queue = append(queue, dep)
			}
		}
	}
	return nil
}
