func (n *Node) ID() uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(n.AbsPath))
	return h.Sum32()
}

type Graph struct {
	Nodes []*Node // BFS load order
	ByAbs map[string]*Node
	Entrypoints []string
}

type Ignorer struct {
	Only    []string
	Exclude []string
}

func (ig *Ignorer) IsIgnored(absPath string) bool {
	if ig == nil {
		return false
	}
	for _, p := range ig.Exclude {
		if ok, _ := globutil.Match(p, absPath); ok {
			return true
		}
	}
	if len(ig.Only) > 0 {
		for _, p := range ig.Only {
			if ok, _ := globutil.Match(p, absPath); ok {
				return false
			}
		}
		return true
	}
	return false
}

type Progress interface {
	Start()
	Update(loaded, total int)
	Finish(loaded, total int)
}

type noopProgress struct{}
func (noopProgress) Start() {}
func (noopProgress) Update(int,int) {}
func (noopProgress) Finish(int,int) {}

// Load parses entrypoints breadth-first following dependencies.
func Load(entrypoints []string, parser language.Parser, ignorer *Ignorer, progress Progress) (*Graph, error) {
	if progress == nil {
		progress = noopProgress{}
	}
	progress.Start()
	g := &Graph{ByAbs: map[string]*Node{}, Entrypoints: append([]string(nil), entrypoints...)}
	seen := map[string]bool{}
	var queue []string
	for _, e := range entrypoints {
		e = filepath.Clean(e)
		if !seen[e] {
			seen[e] = true
			queue = append(queue, e)
		}
	}
	total := len(queue)
	loaded := 0
	type pending struct {
		node *Node
		rawDeps []string
	}
	var pend []*pending
	for i := 0; i < len(queue); i++ {
		abs := queue[i]
		if ignorer.IsIgnored(abs) {
			continue
		}
		pf, err := parser.ParseFile(abs)
		if err != nil {
			return nil, err
		}
		node := &Node{AbsPath: abs, DisplayPath: pf.DisplayPath, Group: pf.Group, Loc: pf.Loc, Errors: pf.Errors}
		g.Nodes = append(g.Nodes, node)
		g.ByAbs[abs] = node
		pend = append(pend, &pending{node: node, rawDeps: pf.Dependencies})
		loaded++
		for _, dep := range pf.Dependencies {
			dep = filepath.Clean(dep)
			if dep == abs {
				continue
			}
			if ignorer.IsIgnored(dep) {
				continue
			}
			if !seen[dep] {
				seen[dep] = true
				queue = append(queue, dep)
				total++
			}
		}
		progress.Update(loaded, total)
	}
	// Resolve adjacency to loaded nodes, dedupe preserve order, drop self.
	for _, p := range pend {
		dedup := map[string]bool{}
		for _, dep := range p.rawDeps {
			dep = filepath.Clean(dep)
			if dep == p.node.AbsPath || dedup[dep] {
				continue
			}
			if _, ok := g.ByAbs[dep]; !ok {
				continue
			}
			dedup[dep] = true
			p.node.Dependencies = append(p.node.Dependencies, dep)
		}
	}
	progress.Finish(loaded, total)
	return g, nil
}

