package progress

import (
	"fmt"
	"os"
	"strings"
	"time"
)

// Bar renders a spinner-style progress indicator to stderr, mimicking the
// textual shape used by the original tool. Rates are inherently timing
// dependent, so only the overall format is reproduced.
type Bar struct {
	start time.Time
	ops   int
	last  string
	done  bool
}

func New() *Bar { return &Bar{start: time.Now()} }

func (b *Bar) rate() string {
	if b.ops == 0 {
		return "0 it/hr"
	}
	elapsed := time.Since(b.start).Seconds()
	if elapsed <= 0 {
		elapsed = 0.000001
	}
	r := float64(b.ops) / elapsed
	// progressbar formats large rates as integer it/s.
	return fmt.Sprintf("%d it/s", int(r))
}

func (b *Bar) render(desc string) {
	var line string
	if desc == "" {
		line = fmt.Sprintf("⠋  (%s) [0s] ", b.rate())
	} else {
		line = fmt.Sprintf("⠋ %s (%s) [0s] ", desc, b.rate())
	}
	if b.last != "" {
		// Clear previous line in the same spirit as progressbar's blank render.
		fmt.Fprintf(os.Stderr, "\r%s\r", strings.Repeat(" ", visualLen(b.last)))
	}
	fmt.Fprintf(os.Stderr, "\r%s", line)
	b.last = line
}

func visualLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

func (b *Bar) Start() {
	b.start = time.Now()
	b.render("")
	b.ops++
	b.render("")
}

func (b *Bar) Update(loaded, total int) {
	desc := fmt.Sprintf("(%d/%d) Loading Files...", loaded, total)
	b.ops++
	b.render(desc)
	b.ops++
	b.render(desc)
}

func (b *Bar) Finish(loaded, total int) {
	if b.done {
		return
	}
	b.done = true
	desc := fmt.Sprintf("(%d/%d) Finished loading", loaded, total)
	b.ops++
	b.render(desc)
	b.ops++
	b.render(desc)
	fmt.Fprint(os.Stderr, "\n")
}
EOF
