			return base + ".py", true
		}
		if isFile(base + ".pyi") {
			return base + ".pyi", true
		}
		if isDir(base) {
			init := filepath.Join(base, "__init__.py")
			if isFile(init) {
				return init, true
			}
			return "", true
		}
	}
	return "", false
}

func resolveNames(dir string, names []string) ([]string, []string) {
	var deps, errs []string
	for _, name := range names {
		if name == "*" {
			init := filepath.Join(dir, "__init__.py")
			if isFile(init) {
				deps = append(deps, init)
			}
			continue
		}
		parts := strings.Split(name, ".")
		cand := filepath.Join(append([]string{dir}, parts...)...) + ".py"
		if isFile(cand) {
			deps = append(deps, cand)
			continue
		}
		init := filepath.Join(dir, "__init__.py")
		if isFile(init) {
			deps = append(deps, init)
			continue
		}
		errs = append(errs, fmt.Sprintf("cannot import file %s.py from directory %s", name, dir))
	}
	return deps, errs
}

func (p *Parser) resolveFromAbsolute(dirs []string, dotted string, names []string) ([]string, []string) {
	parts := strings.Split(dotted, ".")
	for _, d := range dirs {
		base := filepath.Join(append([]string{d}, parts...)...)
		if isFile(base + ".py") {
			return []string{base + ".py"}, nil
		}
		if isFile(base + ".pyi") {
			return []string{base + ".pyi"}, nil
		}
		if isDir(base) {
			return resolveNames(base, names)
		}
	}
	return nil, nil
}

func (p *Parser) resolveRelative(fileDir string, level int, dotted string, names []string) ([]string, []string) {
	target := fileDir
	for i := 1; i < level; i++ {
		target = filepath.Dir(target)
	}
	if dotted == "" {
		base := target
		if isFile(base + ".py") {
			return []string{base + ".py"}, nil
		}
		if isFile(base + ".pyi") {
			return []string{base + ".pyi"}, nil
		}
		if isDir(base) {
			return resolveNames(base, names)
		}
		// Directory does not exist (climbed above root): names cannot be imported.
		return resolveNames(base, names)
	}
	parts := strings.Split(dotted, ".")
	base := filepath.Join(append([]string{target}, parts...)...)
	if isFile(base + ".py") {
		return []string{base + ".py"}, nil
	}
	if isFile(base + ".pyi") {
		return []string{base + ".pyi"}, nil
	}
	if isDir(base) {
		return resolveNames(base, names)
	}
	shown := target + "/" + strings.Join(parts, "/")
	return nil, []string{fmt.Sprintf("could not resolve relative import from %s to %s", fileDir, shown)}
}

var (
	fromRe   = regexp.MustCompile(`^from\s+(\.*(?:\s*[A-Za-z_][A-Za-z0-9_]*(?:\s*\.\s*[A-Za-z_][A-Za-z0-9_]*)*)?)\s+import\s+(.+)$`)
	importRe = regexp.MustCompile(`^import\s+([A-Za-z_][A-Za-z0-9_]*(?:\s*\.\s*[A-Za-z_][A-Za-z0-9_]*)*)`)
	afterColonRe = regexp.MustCompile(`:\s*((?:from|import)\s+.+)$`)
	identColonRe = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*\s*:`)
)

func cleanDotted(s string) string {
	s = strings.Map(func(r rune) rune {
		if r == ' ' || r == '\t' {
			return -1
		}
		return r
	}, s)
	return s
}

func parseNames(s string) []string {
	s = strings.TrimSpace(s)
	// Remove surrounding parentheses (possibly multiline already joined).
	s = strings.Trim(s, "()")
	var out []string
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(strings.Trim(part, "()"))
		if part == "" {
			continue
		}
		if idx := strings.Index(part, " as "); idx >= 0 {
			part = strings.TrimSpace(part[:idx])
		}
		part = cleanDotted(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func firstWord(s string) string {
	f := strings.FieldsFunc(s, func(r rune) bool {
		return !(r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9'))
	})
	if len(f) == 0 {
		return ""
	}
	return f[0]
}

func (p *Parser) ParseFile(abs string) (*language.ParsedFile, error) {
	abs = filepath.Clean(abs)
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	fileDir := filepath.Dir(abs)
	root := p.findRoot(fileDir)
	dirs := p.searchDirs(fileDir, root)
	cleaned := stripStringsAndComments(string(data))
	lines := logicalLines(cleaned)
	var deps []string
	var errs []string
	seenDep := map[string]bool{}
	add := func(ds []string) {
		for _, d := range ds {
			d = filepath.Clean(d)
			if !seenDep[d] {
				seenDep[d] = true
				deps = append(deps, d)
			}
		}
	}
	for _, line := range lines {
		indented := len(line) > 0 && (line[0] == ' ' || line[0] == '\t')
		segments := strings.Split(line, ";")
		for _, seg := range segments {
			segTrim := strings.TrimSpace(seg)
			if segTrim == "" {
				continue
			}
			stmt := ""
			conditional := indented
			if strings.HasPrefix(segTrim, "import ") || strings.HasPrefix(segTrim, "import\t") || strings.HasPrefix(segTrim, "from ") || strings.HasPrefix(segTrim, "from\t") {
				stmt = segTrim
			} else if m := afterColonRe.FindStringSubmatch(segTrim); m != nil {
				fw := firstWord(segTrim)
				if fw == "else" || fw == "try" || fw == "except" || fw == "finally" || fw == "lambda" {
					continue
				}
				if identColonRe.MatchString(segTrim) {
					continue
				}
				stmt = strings.TrimSpace(m[1])
				conditional = true
			} else {
				// Fallback for a wrapped line like "a import x" produced by a
				// backslash continuation on the previous physical line.
				if idx := strings.Index(segTrim, " import "); idx > 0 {
					cand := strings.TrimSpace(segTrim[idx+1:])
					if importRe.MatchString(cand) {
						stmt = cand
					} else {
						continue
					}
				} else {
					continue
				}
			}
			if p.ExcludeConditional && conditional {
				continue
			}
			if strings.HasPrefix(stmt, "from") {
				m := fromRe.FindStringSubmatch(stmt)
				if m == nil {
					continue
				}
				rawMod := cleanDotted(m[1])
				names := parseNames(m[2])
				level := 0
				for level < len(rawMod) && rawMod[level] == '.' {
					level++
				}
				dotted := rawMod[level:]
				var ds, es []string
				if level > 0 {
					ds, es = p.resolveRelative(fileDir, level, dotted, names)
				} else {
					if dotted == "" {
						continue
					}
					ds, es = p.resolveFromAbsolute(dirs, dotted, names)
				}
				add(ds)
				errs = append(errs, es...)
			} else {
				m := importRe.FindStringSubmatch(stmt)
				if m == nil {
					continue
				}
				dotted := cleanDotted(m[1])
				if dep, ok := p.resolvePlain(dirs, dotted); ok && dep != "" {
					add([]string{dep})
				}
			}
		}
	}
	return &language.ParsedFile{
		AbsPath: abs, DisplayPath: p.RelPath(abs), Loc: loc,
		Dependencies: deps, Errors: errs,
	}, nil
}

func logicalLines(s string) []string {
	phys := strings.Split(s, "\n")
	var out []string
	var buf strings.Builder
	depth := 0
	for i, line := range phys {
		if i > 0 && depth > 0 {
			buf.WriteString(" ")
		}
		buf.WriteString(line)
		for _, r := range line {
			if r == '(' {
				depth++
			} else if r == ')' && depth > 0 {
				depth--
			}
		}
		if depth <= 0 {
			depth = 0
			out = append(out, buf.String())
			buf.Reset()
		}
	}
	if buf.Len() > 0 {
		out = append(out, buf.String())
	}
	return out
}

// stripStringsAndComments replaces string and comment contents with spaces,
// preserving newlines so line structure (indentation) is unchanged.
func stripStringsAndComments(src string) string {
	rs := []rune(src)
	out := make([]rune, len(rs))
	copy(out, rs)
	i := 0
	for i < len(rs) {
		c := rs[i]
		if c == '#' {
			for i < len(rs) && rs[i] != '\n' {
				out[i] = ' '
				i++
			}
			continue
		}
		if c == '"' || c == '\'' {
			// Determine if triple-quoted.
			triple := i+2 < len(rs) && rs[i+1] == c && rs[i+2] == c
			raw := isRawPrefix(out, i)
			if triple {
				for k := 0; k < 3 && i < len(rs); k++ {
					out[i] = ' '
					i++
				}
				for i < len(rs) {
					if !raw && rs[i] == '\\' && i+1 < len(rs) {
						out[i] = ' '
						if rs[i+1] != '\n' {
							out[i+1] = ' '
						}
						i += 2
						continue
					}
					if rs[i] == c && i+2 < len(rs) && rs[i+1] == c && rs[i+2] == c {
						for k := 0; k < 3; k++ {
							out[i] = ' '
							i++
						}
						break
					}
					if rs[i] != '\n' {
						out[i] = ' '
					}
					i++
				}
				continue
			}
			out[i] = ' '
			i++
			for i < len(rs) && rs[i] != '\n' {
				if !raw && rs[i] == '\\' && i+1 < len(rs) {
					out[i] = ' '
					if rs[i+1] != '\n' {
						out[i+1] = ' '
					}
					i += 2
					continue
				}
				isEnd := rs[i] == c
				out[i] = ' '
				i++
				if isEnd {
					break
				}
			}
			continue
		}
		i++
	}
	return string(out)
}

func isRawPrefix(out []rune, quoteIdx int) bool {
	j := quoteIdx - 1
	hasRaw := false
	for j >= 0 {
		r := out[j]
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
			if r == 'r' || r == 'R' {
				hasRaw = true
			}
			j--
			continue
		}
		break
	}
	return hasRaw
}
