var candidateExts = []string{"js", "ts", "tsx", "jsx", "d.ts", "mjs", "cjs"}

type Parser struct {
	UnwrapExports bool
	Workspaces    bool
	TsConfigPaths bool

	rootCache map[string]rootInfo
	parsed    map[string]*internalFile
	wsCache   map[string]map[string]workspacePkg
	tsCache   map[string]*tsconfigResult
}

type rootInfo struct {
	dir   string
	name  string
	found bool
}

func NewParser(unwrap, workspaces, tsPaths bool) *Parser {
	return &Parser{
		UnwrapExports: unwrap, Workspaces: workspaces, TsConfigPaths: tsPaths,
		rootCache: map[string]rootInfo{}, parsed: map[string]*internalFile{},
		wsCache: map[string]map[string]workspacePkg{}, tsCache: map[string]*tsconfigResult{},
	}
}

func (p *Parser) findRoot(fileDir string) rootInfo {
	if v, ok := p.rootCache[fileDir]; ok {
		return v
	}
	var out rootInfo
	for d := fileDir; ; d = filepath.Dir(d) {
		pkgPath := filepath.Join(d, "package.json")
		if data, err := os.ReadFile(pkgPath); err == nil {
			var raw struct {
				Name string `json:"name"`
			}
			if err := json.Unmarshal(data, &raw); err == nil && raw.Name != "" {
				out = rootInfo{dir: d, name: raw.Name, found: true}
				break
			}
		}
		if filepath.Dir(d) == d {
			break
		}
	}
	p.rootCache[fileDir] = out
	return out
}

func (p *Parser) RelPath(abs string) string {
	abs = filepath.Clean(abs)
	root := p.findRoot(filepath.Dir(abs))
	if !root.found {
		return ""
	}
	rel, err := filepath.Rel(root.dir, abs)
	if err != nil {
		return ""
	}
	return filepath.ToSlash(rel)
}

func isFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}
func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func stripKnownExt(path string) string {
	ext := filepath.Ext(path) // ".ts" for a.d.ts
	if ext != "" {
		for _, e := range candidateExts {
			if "."+e == ext {
				return strings.TrimSuffix(path, ext)
			}
		}
		// ".d.ts" is represented by Ext .ts, already covered.
	}
	return path
}

func resolveFileOrDir(target string) (string, bool) {
	target = filepath.Clean(target)
	base := target
	if isDir(target) {
		base = filepath.Join(target, "index")
		for _, e := range candidateExts {
			cand := base + "." + e
			if isFile(cand) {
				return cand, true
			}
		}
		return "", false
	}
	base = stripKnownExt(target)
	for _, e := range candidateExts {
		cand := base + "." + e
		if isFile(cand) {
			return cand, true
		}
	}
	return "", false
}

type workspacePkg struct {
	dir  string
	main string
}

type workspacesField struct {
	Packages []string
}

func (w *workspacesField) UnmarshalJSON(data []byte) error {
	var arr []string
	if err := json.Unmarshal(data, &arr); err == nil {
		w.Packages = arr
		return nil
	}
	var obj struct {
		Packages []string `json:"packages"`
	}
	if err := json.Unmarshal(data, &obj); err != nil {
		return err
	}
	w.Packages = obj.Packages
	return nil
}

type packageJSON struct {
	Name       string          `json:"name"`
	Main       string          `json:"main"`
	Workspaces workspacesField `json:"workspaces"`
}

// findWorkspaceRoot walks up from fileDir for a package.json carrying
// a non-empty workspaces field.
func (p *Parser) workspaceMap(fileDir string) (map[string]workspacePkg, string) {
	// Cache keyed by starting package root dir (or fileDir if none).
	cacheKey := fileDir
	if root := p.findRoot(fileDir); root.found {
		cacheKey = root.dir
	}
	if m, ok := p.wsCache[cacheKey]; ok {
		return m, ""
	}
	result := map[string]workspacePkg{}
	wsRoot := ""
	var patterns []string
	for d := fileDir; ; d = filepath.Dir(d) {
		data, err := os.ReadFile(filepath.Join(d, "package.json"))
		if err == nil {
			var pj packageJSON
			if err := json.Unmarshal(data, &pj); err == nil && len(pj.Workspaces.Packages) > 0 {
				wsRoot = d
				patterns = pj.Workspaces.Packages
				break
			}
		}
		if filepath.Dir(d) == d {
			break
		}
	}
	if wsRoot != "" {
		for _, pat := range patterns {
			globPat := pat
			if !filepath.IsAbs(globPat) {
				globPat = filepath.Join(wsRoot, globPat)
			}
			matches, err := globutil.Glob(filepath.ToSlash(globPat))
			if err != nil {
				continue
			}
			for _, m := range matches {
				if !isDir(m) {
					continue
				}
				pkgPath := filepath.Join(m, "package.json")
				data, err := os.ReadFile(pkgPath)
				if err != nil {
					continue
				}
				var pj packageJSON
				if err := json.Unmarshal(data, &pj); err != nil {
					p.wsCache[cacheKey] = result
					return result, fmt.Sprintf("error parsing \"%s\": %s", pkgPath, err)
				}
				if pj.Name != "" {
					if _, exists := result[pj.Name]; !exists {
						result[pj.Name] = workspacePkg{dir: m, main: pj.Main}
					}
				}
			}
		}
	}
	p.wsCache[cacheKey] = result
	return result, ""
}

type tsconfigFile struct {
	CompilerOptions struct {
		BaseURL *string             `json:"baseUrl"`
		Paths   map[string][]string `json:"paths"`
	} `json:"compilerOptions"`
}

type tsconfigResult struct {
	cfg *tsconfigFile
	err string
}

func (p *Parser) tsconfig(rootDir string) *tsconfigResult {
	if v, ok := p.tsCache[rootDir]; ok {
		return v
	}
	res := &tsconfigResult{}
	path := filepath.Join(rootDir, "tsconfig.json")
	data, err := os.ReadFile(path)
	if err == nil {
		std, herr := standardizeJSONC(string(data))
		if herr != "" {
			res.err = fmt.Sprintf("found TypeScript config file in %s but there was an error reading it: %s", path, herr)
		} else {
			var cfg tsconfigFile
			if err := json.Unmarshal([]byte(std), &cfg); err != nil {
				res.err = fmt.Sprintf("found TypeScript config file in %s but there was an error reading it: %s", path, err)
			} else {
				res.cfg = &cfg
			}
		}
	}
	p.tsCache[rootDir] = res
	return res
}

// standardizeJSONC strips comments and trailing commas. It returns a
// hujson-flavoured error string for obvious invalid literals.
func standardizeJSONC(src string) (string, string) {
	trimmed := strings.TrimSpace(src)
	if trimmed == "" {
		return "", "hujson: line 1, column 1: unexpected end of JSON input"
	}
	// Detect a bare invalid literal at the start, like hujson does.
	if c := trimmed[0]; !(c == '{' || c == '[' || c == '"' || c == '-' || (c >= '0' && c <= '9')) {
		word := trimmed
		if idx := strings.IndexAny(trimmed, " \t\r\n"); idx >= 0 {
			word = trimmed[:idx]
		}
		if word != "true" && word != "false" && word != "null" {
			return "", fmt.Sprintf("hujson: line 1, column 1: invalid literal: %s", word)
		}
	}
	// Strip comments outside strings.
	var b strings.Builder
	runes := []rune(src)
	inStr := false
	for i := 0; i < len(runes); i++ {
		c := runes[i]
		if inStr {
			b.WriteRune(c)
			if c == '\\' && i+1 < len(runes) {
				b.WriteRune(runes[i+1])
				i++
			} else if c == '"' {
				inStr = false
			}
			continue
		}
		if c == '"' {
			inStr = true
			b.WriteRune(c)
			continue
		}
		if c == '/' && i+1 < len(runes) && runes[i+1] == '/' {
			for i < len(runes) && runes[i] != '\n' {
				i++
			}
			if i < len(runes) {
				b.WriteRune('\n')
			}
			continue
		}
		if c == '/' && i+1 < len(runes) && runes[i+1] == '*' {
			i += 2
			for i+1 < len(runes) && !(runes[i] == '*' && runes[i+1] == '/') {
				if runes[i] == '\n' {
					b.WriteRune('\n')
				}
				i++
			}
			i++
			continue
		}
		b.WriteRune(c)
	}
	// Remove trailing commas before ] or }.
	s := b.String()
	var out strings.Builder
	rs := []rune(s)
	inStr = false
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		if inStr {
			out.WriteRune(c)
			if c == '\\' && i+1 < len(rs) {
				out.WriteRune(rs[i+1])
				i++
			} else if c == '"' {
				inStr = false
			}
			continue
		}
		if c == '"' {
			inStr = true
			out.WriteRune(c)
			continue
		}
		if c == ',' {
			j := i + 1
			for j < len(rs) && (rs[j] == ' ' || rs[j] == '\t' || rs[j] == '\n' || rs[j] == '\r') {
				j++
			}
			if j < len(rs) && (rs[j] == ']' || rs[j] == '}') {
				continue
			}
		}
		out.WriteRune(c)
	}
	return out.String(), ""
}

// resolveSpecifier returns (absPath, errorString). absPath=="" && errorString=="" means external/unresolved silently.
func (p *Parser) resolveSpecifier(importerAbs, spec string) (string, string) {
	if spec == "" {
		return "", "import path cannot be empty"
	}
	if len(spec) == 1 {
		return "", fmt.Sprintf("invalid import path %s", spec)
	}
	fileDir := filepath.Dir(importerAbs)
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "..") {
		target := filepath.Join(fileDir, spec)
		if resolved, ok := resolveFileOrDir(target); ok {
			return resolved, ""
		}
		return "", fmt.Sprintf("could not perform relative import for '%s' because the file or dir was not found", spec)
	}
	// Bare specifier: workspaces first.
	if p.Workspaces {
		pkgName, sub := splitPackage(spec)
		wsMap, wsErr := p.workspaceMap(fileDir)
		if wsErr != "" {
			return "", wsErr
		}
		if ws, ok := wsMap[pkgName]; ok {
			var candidate string
			if sub != "" {
				candidate = filepath.Join(ws.dir, sub)
			} else if ws.main != "" {
				candidate = filepath.Join(ws.dir, ws.main)
			} else {
				candidate = ws.dir
			}
			if resolved, ok := resolveFileOrDir(candidate); ok {
				return resolved, ""
			}
			return "", fmt.Sprintf("path '%s' matched workspace '%s', but no file '%s' does not exist", spec, pkgName, candidate)
		}
	}
	if p.TsConfigPaths {
		root := p.findRoot(fileDir)
		if root.found {
			tsr := p.tsconfig(root.dir)
			if tsr.err != "" {
				return "", tsr.err
			}
			if tsr.cfg != nil {
				baseDir := root.dir
				hasBase := false
				if tsr.cfg.CompilerOptions.BaseURL != nil {
					hasBase = true
					baseDir = filepath.Join(root.dir, *tsr.cfg.CompilerOptions.BaseURL)
				}
				if hasBase {
					candidate := filepath.Join(baseDir, spec)
					if resolved, ok := resolveFileOrDir(candidate); ok {
						return resolved, ""
					}
				}
				var firstMatched string
				for pattern, targets := range tsr.cfg.CompilerOptions.Paths {
					capture, ok := matchTsPattern(pattern, spec)
					if !ok {
						continue
					}
					for _, target := range targets {
						replaced := target
						if strings.Contains(replaced, "*") {
							replaced = strings.Replace(replaced, "*", capture, 1)
						}
						candidate := filepath.Join(baseDir, replaced)
						if firstMatched == "" {
							firstMatched = candidate
						}
						if resolved, ok := resolveFileOrDir(candidate); ok {
							return resolved, ""
						}
					}
				}
				if firstMatched != "" {
					return "", fmt.Sprintf("import '%s' was matched to path '%s' in tscofing's paths option, but the resolved path did not match an existing file", spec, firstMatched)
				}
			}
		}
	}
	return "", ""
}

func splitPackage(spec string) (string, string) {
	parts := strings.Split(spec, "/")
	if strings.HasPrefix(spec, "@") && len(parts) >= 2 {
		return parts[0] + "/" + parts[1], strings.Join(parts[2:], "/")
	}
	if len(parts) > 1 {
		return parts[0], strings.Join(parts[1:], "/")
	}
	return spec, ""
}

func matchTsPattern(pattern, spec string) (string, bool) {
	idx := strings.Index(pattern, "*")
	if idx < 0 {
		if pattern == spec {
			return "", true
		}
		return "", false
	}
	prefix := pattern[:idx]
	suffix := pattern[idx+1:]
	if strings.HasPrefix(spec, prefix) && strings.HasSuffix(spec, suffix) && len(spec) >= len(prefix)+len(suffix) {
		return spec[len(prefix) : len(spec)-len(suffix)], true
	}
	return "", false
}
