			j := i + 1
			inClass := false
			ok := false
			for j < len(rs) {
				if rs[j] == '\\' {
					j += 2
					continue
				}
				if rs[j] == '\n' {
					break
				}
				if rs[j] == '[' {
					inClass = true
				} else if rs[j] == ']' {
					inClass = false
				} else if rs[j] == '/' && !inClass {
					ok = true
					j++
					break
				}
				j++
