			for i+1 < len(rs) && !(rs[i] == '*' && rs[i+1] == '/') {
				i++
			}
			i += 2
			continue
		}
		// Regex literal heuristic: a '/' that is not division. Division if
		// previous token could end an expression (ident/number/string/`)`/`]`/template).
		if c == '/' && canStartRegex(toks) {
			// Consume regex including character classes and flags.
			j := i + 1
			inClass := false
			ok := false
			for j < len(rs) {
				if rs[j] == '\\' {
					j += 2
					continue
				}
				if rs[j] == '\n' {
					break
				}
				if rs[j] == '[' {
					inClass = true
				} else if rs[j] == ']' {
					inClass = false
				} else if rs[j] == '/' && !inClass {
					ok = true
					j++
					break
				}
				j++
			}
			if ok {
				for j < len(rs) && isIdentPart(rs[j]) {
					j++
				}
				toks = append(toks, token{kind: tString, text: ""})
				i = j
				continue
			}
			// Fall through as punct.
		}
		if c == '"' || c == '\'' {
			q := c
			i++
			var sb strings.Builder
			for i < len(rs) && rs[i] != '\n' {
				if rs[i] == '\\' && i+1 < len(rs) {
					esc := rs[i+1]
					switch esc {
					case 'n':
						sb.WriteRune('\n')
					case 't':
						sb.WriteRune('\t')
					case 'r':
						sb.WriteRune('\r')
					default:
						sb.WriteRune(esc)
					}
					i += 2
					continue
				}
				if rs[i] == q {
					i++
					break
				}
				sb.WriteRune(rs[i])
				i++
			}
			toks = append(toks, token{kind: tString, text: sb.String()})
			continue
		}
		if c == '`' {
			// Consume template literal, including ${} with brace counting.
			i++
			depth := 0
			for i < len(rs) {
				if rs[i] == '\\' {
					i += 2
					continue
				}
				if depth == 0 && rs[i] == '`' {
					i++
					break
				}
				if rs[i] == '$' && i+1 < len(rs) && rs[i+1] == '{' {
					depth++
					i += 2
					continue
				}
				if depth > 0 && (rs[i] == '"' || rs[i] == '\'' || rs[i] == '`') {
					q := rs[i]
					i++
					for i < len(rs) {
						if rs[i] == '\\' {
							i += 2
							continue
						}
						if rs[i] == q {
							i++
							break
						}
						if q != '`' && rs[i] == '\n' {
							break
						}
						i++
					}
					continue
				}
				if depth > 0 && rs[i] == '{' {
					depth++
				} else if depth > 0 && rs[i] == '}' {
					depth--
				}
				i++
			}
			toks = append(toks, token{kind: tTemplate, text: ""})
			continue
		}
		if isIdentStart(c) {
			j := i
			for j < len(rs) && isIdentPart(rs[j]) {
				j++
			}
			toks = append(toks, token{kind: tIdent, text: string(rs[i:j])})
			i = j
			continue
		}
		if c >= '0' && c <= '9' {
			j := i
			for j < len(rs) && (isIdentPart(rs[j]) || rs[j] == '.') {
				j++
			}
			toks = append(toks, token{kind: tNumber, text: string(rs[i:j])})
			i = j
			continue
		}
		// Punctuation: keep "..." as one token for rest/spread detection.
		if c == '.' && i+2 < len(rs) && rs[i+1] == '.' && rs[i+2] == '.' {
			toks = append(toks, token{kind: tPunct, text: "..."})
			i += 3
			continue
		}
		toks = append(toks, token{kind: tPunct, text: string(c)})
		i++
	}
	return toks
}

func canStartRegex(toks []token) bool {
	if len(toks) == 0 {
		return true
	}
	last := toks[len(toks)-1]
	switch last.kind {
	case tIdent:
		switch last.text {
		case "return", "typeof", "case", "delete", "void", "in", "of", "new", "throw", "await", "yield":
			return true
		}
		return false
	case tNumber, tString, tTemplate:
		return false
	case tPunct:
		return !(last.text == ")" || last.text == "]" || last.text == "}")
	}
	return true
}
