{"command":"cat > internal/js/parsefile.go <<'EOF'
package js

import (
	"fmt"
	"path/filepath"
	"strings"

	"deptree/internal/graph"
	"deptree/internal/language"
)

type namePair struct {
	orig     string
	exported string
	typeOnly bool
}

type stmt struct {
	spec          string
	target        string
	resolutionErr string
	isExportFrom  bool
	isStar        bool
	isStarAs      bool
	starNs        string
	depSymbols    []string
	reexports     []namePair
}

type exportEventKind int

const (
	evLocal exportEventKind = iota
	evNamedReexport
	evStar
	evStarAs
)

type exportEvent struct {
	kind   exportEventKind
	symbol string
	pairs  []namePair
	stmt   *stmt
}

type internalFile struct {
	abs        string
	display    string
	group      string
	loc        int
	stmts      []*stmt
	events     []exportEvent
	resErrs    []string
	exports    map[string]string
	exportOrder []string
	exportsDone bool
	inProgress bool
	cycleErrs  []string
}

func isIdent(tok token, s string) bool { return tok.kind == tIdent && tok.text == s }
func isPunct(tok token, s string) bool { return tok.kind == tPunct && tok.text == s }

// parseNamedList parses tokens starting at '{' (index i). Returns pairs and index just past '}'.
func parseNamedList(toks []token, i int, exportCtx bool) ([]namePair, int) {
	// toks[i] == '{'
 depth := 0
	var entries [][]token
	var cur []token
	j := i
	for ; j < len(toks); j++ {
		t := toks[j]
		if isPunct(t, "{") {
			depth++
			if depth == 1 {
				continue
			}
		} else if isPunct(t, "}") {
			depth--
			if depth == 0 {
				if len(cur) > 0 {
					entries = append(entries, cur)
				}
				j++
				break
			}
		}
		if depth == 1 && isPunct(t, ",") {
			entries = append(entries, cur)
			cur = nil
			continue
		}
		if depth >= 1 {
			cur = append(cur, t)
		}
	}
	var pairs []namePair
	for _, e := range entries {
		if len(e) == 0 {
			continue
		}
		// Type-only entry: "type" IDENT (with optional as IDENT).
		typeOnly := false
		if isIdent(e[0], "type") && len(e) >= 2 && !isIdent(e[1], "as") {
			typeOnly = true
			if exportCtx {
				// Type-only re-exports / local type export lists are ignored.
				continue
			}
			e = e[1:]
		}
		var orig, exported string
		if e[0].kind == tString {
			orig = e[0].text
			exported = orig
		} else if e[0].kind == tIdent {
			orig = e[0].text
			exported = orig
		} else {
			continue
		}
		// "as" alias.
		for k := 1; k+1 < len(e); k++ {
			if isIdent(e[k], "as") {
				if e[k+1].kind == tIdent || e[k+1].kind == tString {
					exported = e[k+1].text
				}
				break
			}
		}
		pairs = append(pairs, namePair{orig: orig, exported: exported, typeOnly: typeOnly})
	}
	return pairs, j
}

func (p *Parser) loadInternal(abs string) (*internalFile, error) {
	abs = filepath.Clean(abs)
	if v, ok := p.parsed[abs]; ok {
		return v, nil
	}
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	root := p.findRoot(filepath.Dir(abs))
	in := &internalFile{abs: abs, loc: loc, exports: map[string]string{}}
	in.display = p.RelPath(abs)
	if root.found {
		in.group = root.name
	}
	p.parsed[abs] = in
	toks := lex(string(data))
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		if isIdent(t, "import") {
			// import.meta
			if i+1 < len(toks) && isPunct(toks[i+1], ".") {
				continue
			}
			// Dynamic import.
			if i+2 < len(toks) && isPunct(toks[i+1], "(") {
				if toks[i+2].kind == tString {
					in.stmts = append(in.stmts, &stmt{spec: toks[i+2].text, depSymbols: []string{"*"}})
				}
				continue
			}
			// Side-effect import.
			if i+1 < len(toks) && toks[i+1].kind == tString {
				in.stmts = append(in.stmts, &stmt{spec: toks[i+1].text, depSymbols: []string{"*"}})
				continue
			}
			// Import clause.
			j := i + 1
			var symbols []string
			if j < len(toks) && isIdent(toks[j], "type") && j+1 < len(toks) && !isIdent(toks[j+1], "from") && !isPunct(toks[j+1], ",") {
				j++ // type-only import modifier
			}
			// Default binding.
			if j < len(toks) && toks[j].kind == tIdent && !isIdent(toks[j], "from") {
				symbols = append(symbols, "default")
				j++
				if j < len(toks) && isPunct(toks[j], ",") {
					j++
				}
			}
			if j < len(toks) && isPunct(toks[j], "*") {
				symbols = append(symbols, "*")
				j++
				if j < len(toks) && isIdent(toks[j], "as") {
					j += 2
				}
			} else if j < len(toks) && isPunct(toks[j], "{") {
				pairs, after := parseNamedList(toks, j, false)
				for _, pr := range pairs {
					symbols = append(symbols, pr.orig)
				}
				j = after
			}
			if j+1 < len(toks) && isIdent(toks[j], "from") && toks[j+1].kind == tString {
				if len(symbols) == 0 {
					symbols = []string{"*"}
				}
				in.stmts = append(in.stmts, &stmt{spec: toks[j+1].text, depSymbols: symbols})
			}
			continue
		}
		if isIdent(t, "export") {
			if i+1 >= len(toks) {
				continue
			}
			nx := toks[i+1]
			if isPunct(nx, "*") {
				j := i + 2
				if j+1 < len(toks) && isIdent(toks[j], "as") && toks[j+1].kind == tIdent {
					ns := toks[j+1].text
					j += 2
					if j+1 < len(toks) && isIdent(toks[j], "from") && toks[j+1].kind == tString {
						st := &stmt{spec: toks[j+1].text, isExportFrom: true, isStarAs: true, starNs: ns, depSymbols: []string{ns}}
						in.stmts = append(in.stmts, st)
						in.events = append(in.events, exportEvent{kind: evStarAs, symbol: ns, stmt: st})
					}
				} else if j+1 < len(toks) && isIdent(toks[j], "from") && toks[j+1].kind == tString {
					st := &stmt{spec: toks[j+1].text, isExportFrom: true, isStar: true, depSymbols: []string{"*"}}
					in.stmts = append(in.stmts, st)
					in.events = append(in.events, exportEvent{kind: evStar, stmt: st})
				}
				continue
			}
			if isIdent(nx, "type") {
				// export type {X} [from] / export type * ...: ignored.
				// export type Name ...: local type alias.
				if i+2 < len(toks) && toks[i+2].kind == tIdent {
					in.events = append(in.events, exportEvent{kind: evLocal, symbol: toks[i+2].text})
				}
				continue
			}
			if isPunct(nx, "{") {
				pairs, after := parseNamedList(toks, i+1, true)
				if after+1 < len(toks) && isIdent(toks[after], "from") && toks[after+1].kind == tString {
					if len(pairs) > 0 {
						var depSyms []string
						for _, pr := range pairs {
							depSyms = append(depSyms, pr.exported)
						}
						st := &stmt{spec: toks[after+1].text, isExportFrom: true, depSymbols: depSyms, reexports: pairs}
						in.stmts = append(in.stmts, st)
						in.events = append(in.events, exportEvent{kind: evNamedReexport, pairs: pairs, stmt: st})
					}
				} else {
					for _, pr := range pairs {
						in.events = append(in.events, exportEvent{kind: evLocal, symbol: pr.exported})
					}
				}
				continue
			}
			if isIdent(nx, "default") {
				in.events = append(in.events, exportEvent{kind: evLocal, symbol: "default"})
				continue
			}
			// Local declaration forms (only first declarator name).
			if name, ok := localDeclName(toks, i+1); ok {
				in.events = append(in.events, exportEvent{kind: evLocal, symbol: name})
			}
			continue
		}
		if isIdent(t, "require") {
			if i+2 < len(toks) && isPunct(toks[i+1], "(") && toks[i+2].kind == tString {
				syms := requireSymbols(toks, i)
				in.stmts = append(in.stmts, &stmt{spec: toks[i+2].text, depSymbols: syms})
			}
			continue
		}
	}
	// Resolve every statement specifier once.
	for _, st := range in.stmts {
		target, errStr := p.resolveSpecifier(abs, st.spec)
		st.target = target
		st.resolutionErr = errStr
		if errStr != "" {
			in.resErrs = append(in.resErrs, errStr)
		}
	}
	return in, nil
}

func localDeclName(toks []token, j int) (string, bool) {
	if j >= len(toks) || toks[j].kind != tIdent {
		return "", false
	}
	kw := toks[j].text
	switch kw {
	case "const", "let", "var", "class", "interface", "enum":
		if j+1 < len(toks) && toks[j+1].kind == tIdent {
			return toks[j+1].text, true
		}
	case "function":
		k := j + 1
		if k < len(toks) && isPunct(toks[k], "*") {
			k++
		}
		if k < len(toks) && toks[k].kind == tIdent {
			return toks[k].text, true
		}
	case "async":
		if j+1 < len(toks) && isIdent(toks[j+1], "function") {
			k := j + 2
			if k < len(toks) && isPunct(toks[k], "*") {
				k++
			}
			if k < len(toks) && toks[k].kind == tIdent {
				return toks[k].text, true
			}
		}
	}
	return "", false
}

// requireSymbols inspects tokens before a require() call for a simple
// const/let/var {a, b: c} = pattern and returns the property names.
func requireSymbols(toks []token, reqIdx int) []string {
	// Pattern: ... } = require
	if reqIdx >= 2 && isPunct(toks[reqIdx-1], "=") && isPunct(toks[reqIdx-2], "}") {
		// Find matching '{'.
		depth := 0
		start := -1
		for k := reqIdx - 2; k >= 0; k-- {
			if isPunct(toks[k], "}") {
				depth++
			} else if isPunct(toks[k], "{") {
				depth--
				if depth == 0 {
					start = k
					break
				}
			}
		}
		if start > 0 && toks[start-1].kind == tIdent {
			kw := toks[start-1].text
			if kw == "const" || kw == "let" || kw == "var" {
				inner := toks[start+1 : reqIdx-2]
				// Reject nested braces/brackets/spread/defaults.
				valid := true
				for _, t := range inner {
					if isPunct(t, "{") || isPunct(t, "}") || isPunct(t, "[") || isPunct(t, "]") || isPunct(t, "...") || isPunct(t, "=") {
						valid = false
						break
					}
				}
				if valid {
					var syms []string
					// Entries at commas; property name is first ident of entry.
					expectName := true
					for _, t := range inner {
						if isPunct(t, ",") {
							expectName = true
							continue
						}
						if expectName && t.kind == tIdent {
							syms = append(syms, t.text)
							expectName = false
							continue
						}
						if expectName && t.kind == tString {
							syms = append(syms, t.text)
							expectName = false
							continue
						}
						expectName = false
					}
					if len(syms) > 0 {
						return syms
					}
				}
			}
		}
	}
	return []string{"*"}
}

func (in *internalFile) setExport(symbol, origin string) {
	if _, ok := in.exports[symbol]; !ok {
		in.exportOrder = append(in.exportOrder, symbol)
	}
	in.exports[symbol] = origin
}

// exportsOf computes (or returns cached) exports for a file. stack holds the
// chain of files currently being computed, including in.abs as last element.
// It returns cycle errors generated during a fresh computation.
func (p *Parser) exportsOf(in *internalFile, stack []string) (map[string]string, []string) {
	if in.exportsDone {
		return in.exports, nil
	}
	if in.exports == nil {
		in.exports = map[string]string{}
	}
	in.inProgress = true
	var generated []string
	for _, ev := range in.events {
		switch ev.kind {
		case evLocal:
			in.setExport(ev.symbol, in.abs)
		case evStarAs:
			target := ev.stmt.target
			if target == "" {
				target = in.abs
			}
			in.setExport(ev.symbol, target)
		case evNamedReexport:
			target := ev.stmt.target
			for _, pr := range ev.pairs {
				if target == "" {
					in.setExport(pr.exported, in.abs)
					continue
				}
				origin, gen := p.lookupExport(target, pr.orig, stack, in)
				generated = append(generated, gen...)
				in.setExport(pr.exported, origin)
			}
		case evStar:
			target := ev.stmt.target
			if target == "" {
				continue
			}
			if idx := indexOf(stack, target); idx >= 0 {
				errStr := cycleError(stack, idx, target)
				in.cycleErrs = append(in.cycleErrs, errStr)
				generated = append(generated, errStr)
				continue
			}
			tin, err := p.loadInternal(target)
			if err != nil {
				continue
			}
			texp, gen := p.exportsOf(tin, append(append([]string(nil), stack...), target))
			generated = append(generated, gen...)
			for _, sym := range tin.exportOrder {
				in.setExport(sym, texp[sym])
			}
		}
	}
	in.inProgress = false
	in.exportsDone = true
	return in.exports, generated
}

func indexOf(ss []string, s string) int {
	for i, v := range ss {
		if v == s {
			return i
		}
	}
	return -1
}

func cycleError(stack []string, idx int, target string) string {
	var b strings.Builder
	b.WriteString("circular export: cycle detected:\n")
	parts := append(append([]string(nil), stack[idx:]...), target)
	b.WriteString(strings.Join(parts, "\n"))
	return b.String()
}

// lookupExport returns the ultimate origin file for symbol in target file,
// or target itself when the symbol is not found there.
func (p *Parser) lookupExport(target, symbol string, stack []string, current *internalFile) (string, []string) {
	if idx := indexOf(stack, target); idx >= 0 {
		errStr := cycleError(stack, idx, target)
		current.cycleErrs = append(current.cycleErrs, errStr)
		return target, []string{errStr}
	}
	tin, err := p.loadInternal(target)
	if err != nil {
		return target, nil
	}
	texp, gen := p.exportsOf(tin, append(append([]string(nil), stack...), target))
	if origin, ok := texp[symbol]; ok {
		return origin, gen
	}
	return target, gen
}

func (p *Parser) dependenciesOf(in *internalFile) ([]string, []string) {
	var deps []string
	seen := map[string]bool{}
	add := func(d string) {
		if d != "" && !seen[d] {
			seen[d] = true
			deps = append(deps, d)
		}
	}
	var genErrs []string
	for _, st := range in.stmts {
		if st.target == "" {
			continue
		}
		if !p.UnwrapExports {
			if st.isStar {
				tin, err := p.loadInternal(st.target)
				if err != nil {
					continue
				}
				texp, _ := p.exportsOf(tin, []string{st.target})
				if len(texp) == 0 {
					continue
				}
			}
			add(st.target)
			continue
		}
		// Unwrap mode.
		tin, err := p.loadInternal(st.target)
		if err != nil {
			continue
		}
		texp, gen := p.exportsOf(tin, []string{st.target})
		genErrs = append(genErrs, gen...)
		for _, sym := range st.depSymbols {
			if sym == "*" {
				for _, esym := range tin.exportOrder {
					add(texp[esym])
				}
			} else if origin, ok := texp[sym]; ok {
				add(origin)
			}
		}
	}
	return deps, genErrs
}

func dedupeStrings(in []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range in {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}

func (p *Parser) ParseFile(abs string) (*language.ParsedFile, error) {
	in, err := p.loadInternal(abs)
	if err != nil {
		return nil, err
	}
	_, _ = p.exportsOf(in, []string{in.abs})
	deps, genErrs := p.dependenciesOf(in)
	errs := append([]string(nil), in.resErrs...)
	errs = append(errs, in.cycleErrs...)
	if p.UnwrapExports {
		errs = append(errs, genErrs...)
	}
	errs = dedupeStrings(errs)
	return &language.ParsedFile{
		AbsPath: in.abs, DisplayPath: in.display, Group: in.group, Loc: in.loc,
		Dependencies: deps, Errors: errs,
	}, nil
}

