type Parser struct {
	ModulePath string
	ModuleRoot string
	packages   map[string]*pkgInfo // by dir
	loadedFiles map[string]bool
}

type pkgInfo struct {
	dir string
	// package name -> symbol -> file
	byName map[string]map[string]string
	names  []string // package names in first-seen order
	errs   []string
}

func (pi *pkgInfo) primaryName() string {
	for _, n := range pi.names {
		if !strings.HasSuffix(n, "_test") {
			return n
		}
	}
	if len(pi.names) > 0 {
		return pi.names[0]
	}
	return ""
}

type moduleStmt struct {
	_    uintptr
	Path string
}

func parseGoMod(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	lines := strings.Split(string(data), "\n")
	var mod *moduleStmt
	inBlock := ""
	known := map[string]bool{
		"module": true, "go": true, "toolchain": true,
		"require": true, "exclude": true, "replace": true, "retract": true,
	}
	parseRequire := func(args []string, lineNo int) error {
		if len(args) != 2 {
			return fmt.Errorf("%s:%d: usage: require module/path v1.2.3", path, lineNo)
		}
		if !validVersion(args[1]) {
			return fmt.Errorf("%s:%d: require %s: version %q invalid: must be of the form v1.2.3", path, lineNo, args[0], args[1])
		}
		return nil
	}
	for idx, raw := range lines {
		lineNo := idx + 1
		line := stripModComment(raw)
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if inBlock != "" {
			if line == ")" {
				inBlock = ""
				continue
			}
			if inBlock == "require" {
				args := modFields(line)
				if err := parseRequire(args, lineNo); err != nil {
					return "", err
				}
			}
			continue
		}
		fields := modFields(line)
		if len(fields) == 0 {
			continue
		}
		directive := fields[0]
		if !known[directive] {
			return "", fmt.Errorf("%s:%d: unknown directive: %s", path, lineNo, directive)
		}
		if len(fields) > 1 && fields[1] == "(" {
			inBlock = directive
			continue
		}
		switch directive {
		case "module":
			if len(fields) != 2 {
				return "", fmt.Errorf("%s:%d: usage: module module/path", path, lineNo)
			}
			if mod != nil {
				return "", fmt.Errorf("%s:%d: repeated module statement", path, lineNo)
			}
			mod = &moduleStmt{Path: fields[1]}
		case "require":
			if err := parseRequire(fields[1:], lineNo); err != nil {
				return "", err
			}
		}
	}
	// Deliberately dereference a nil module statement when there is no
	// module directive, matching the observed panic behaviour.
	return mod.Path, nil
}

func stripModComment(line string) string {
	// Strip // comments outside quotes (go.mod has minimal quoting).
	inQ := false
	for i := 0; i+1 < len(line); i++ {
		if line[i] == '"' {
			inQ = !inQ
		}
		if !inQ && line[i] == '/' && line[i+1] == '/' {
			return line[:i]
		}
	}
	return line
}

func modFields(line string) []string {
	var out []string
	var cur strings.Builder
	inQ := false
	flush := func() {
		if cur.Len() > 0 {
			s := cur.String()
			if unq, err := strconv.Unquote(s); err == nil {
				s = unq
			} else {
				s = strings.Trim(s, "\"")
			}
			out = append(out, s)
			cur.Reset()
		}
	}
	for _, r := range line {
		if r == '"' {
			inQ = !inQ
			cur.WriteRune(r)
			continue
		}
		if !inQ && (r == ' ' || r == '\t' || r == '(' || r == ')') {
			flush()
			if r == '(' || r == ')' {
				out = append(out, string(r))
			}
			continue
		}
		cur.WriteRune(r)
	}
	flush()
	return out
}

var versionRe = regexp.MustCompile(`^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$`)

func validVersion(v string) bool { return versionRe.MatchString(v) }

func NewParser(firstFile string) (*Parser, error) {
	abs := firstFile
	if !filepath.IsAbs(abs) {
		if a, err := filepath.Abs(abs); err == nil {
			abs = a
		}
	}
	abs = filepath.Clean(abs)
	dir := filepath.Dir(abs)
	var modPath, modFile string
	for d := dir; ; d = filepath.Dir(d) {
		cand := filepath.Join(d, "go.mod")
		if info, err := os.Stat(cand); err == nil && !info.IsDir() {
			modFile = cand
			modPath = d
			break
		}
		if filepath.Dir(d) == d {
			break
		}
	}
	if modFile == "" {
		return nil, fmt.Errorf("no go.mod file found in any parent directory of %s", abs)
	}
	modulePath, err := parseGoMod(modFile)
	if err != nil {
		return nil, err
	}
	p := &Parser{ModulePath: modulePath, ModuleRoot: modPath, packages: map[string]*pkgInfo{}, loadedFiles: map[string]bool{}}
	p.preload()
	return p, nil
}

func (p *Parser) preload() {
	_ = filepath.WalkDir(p.ModuleRoot, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if !d.IsDir() && strings.HasSuffix(d.Name(), ".go") {
			p.loadedFiles[filepath.Clean(path)] = true
			p.scanDir(filepath.Dir(path))
		}
		return nil
	})
}

func (p *Parser) scanDir(dir string) *pkgInfo {
	dir = filepath.Clean(dir)
	if pi, ok := p.packages[dir]; ok {
		return pi
	}
	pi := &pkgInfo{dir: dir, byName: map[string]map[string]string{}}
	p.packages[dir] = pi
	entries, err := os.ReadDir(dir)
	if err != nil {
		return pi
	}
	fset := token.NewFileSet()
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		full := filepath.Join(dir, e.Name())
		f, err := parser.ParseFile(fset, full, nil, parser.SkipObjectResolution)
		if err != nil {
			pi.errs = append(pi.errs, err.Error())
			continue
		}
		if f == nil || f.Name == nil {
			continue
		}
		pkgName := f.Name.Name
		syms, ok := pi.byName[pkgName]
		if !ok {
			syms = map[string]string{}
			pi.byName[pkgName] = syms
			pi.names = append(pi.names, pkgName)
		}
		for _, decl := range f.Decls {
			switch d := decl.(type) {
			case *ast.GenDecl:
				if d.Tok == token.IMPORT {
					continue
				}
				for _, spec := range d.Specs {
					switch s := spec.(type) {
					case *ast.ValueSpec:
						for _, n := range s.Names {
							if _, exists := syms[n.Name]; !exists {
								syms[n.Name] = full
							}
						}
					case *ast.TypeSpec:
						if _, exists := syms[s.Name.Name]; !exists {
							syms[s.Name.Name] = full
						}
					}
				}
			case *ast.FuncDecl:
				if d.Recv == nil {
					if _, exists := syms[d.Name.Name]; !exists {
						syms[d.Name.Name] = full
					}
				}
			}
		}
	}
	return pi
}

func (p *Parser) RelPath(abs string) string {
	abs = filepath.Clean(abs)
	rel, err := filepath.Rel(p.ModuleRoot, abs)
	if err != nil {
		return ""
	}
	return filepath.ToSlash(rel)
}

type importInfo struct {
	selector string // name used in selector expressions ("" for dot imports)
	dot      bool
	symbols  map[string]string
}

func (p *Parser) ParseFile(abs string) (*language.ParsedFile, error) {
	abs = filepath.Clean(abs)
	if !p.loadedFiles[abs] {
		return nil, fmt.Errorf("could not find file %s in any of the loaded packages", abs)
	}
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, abs, data, 0)
	if err != nil {
		return nil, err
	}
	fileDir := filepath.Dir(abs)
	ownPkg := p.scanDir(fileDir)
	ownName := ""
	var ownSymbols map[string]string
	if f.Name != nil {
		ownName = f.Name.Name
	}
	if ownPkg != nil {
		ownSymbols = ownPkg.byName[ownName]
	}
	var fileErrs []string
	// Errors from the file's own package (other files).
	// (Only files other than this one; this file parsed cleanly above.)
	// Import handling.
	selectorImports := map[string]*importInfo{}
	var dotImports []*importInfo
	seenPkgErrDirs := map[string]bool{}
	addPkgErrs := func(pi *pkgInfo) {
		if pi == nil || seenPkgErrDirs[pi.dir] {
			return
		}
		seenPkgErrDirs[pi.dir] = true
		fileErrs = append(fileErrs, pi.errs...)
	}
	for _, spec := range f.Imports {
		rawPath := ""
		if spec.Path != nil {
			if uq, err := strconv.Unquote(spec.Path.Value); err == nil {
				rawPath = uq
			} else {
				rawPath = strings.Trim(spec.Path.Value, "\"`")
			}
		}
		alias := ""
		if spec.Name != nil {
			alias = spec.Name.Name
		}
		if alias == "_" {
			continue
		}
		if !strings.HasPrefix(rawPath, p.ModulePath+"/") {
			continue
		}
		sub := strings.TrimPrefix(rawPath, p.ModulePath+"/")
		pkgDir := filepath.Join(p.ModuleRoot, filepath.FromSlash(sub))
		pi := p.scanDir(pkgDir)
		addPkgErrs(pi)
