	lines := strings.Split(string(data), "\n")
	var mod *moduleStmt
	inBlock := ""
	known := map[string]bool{
		"module": true, "go": true, "toolchain": true,
		"require": true, "exclude": true, "replace": true, "retract": true,
	}
	parseRequire := func(args []string, lineNo int) error {
		if len(args) != 2 {
			return fmt.Errorf("%s:%d: usage: require module/path v1.2.3", path, lineNo)
		}
		if !validVersion(args[1]) {
			return fmt.Errorf("%s:%d: require %s: version %q invalid: must be of the form v1.2.3", path, lineNo, args[0], args[1])
