		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if inBlock != "" {
			if line == ")" {
				inBlock = ""
				continue
			}
			if inBlock == "require" {
				args := modFields(line)
				if err := parseRequire(args, lineNo); err != nil {
					return "", err
				}
			}
			continue
		}
		fields := modFields(line)
		if len(fields) == 0 {
			continue
		}
		directive := fields[0]
		if !known[directive] {
			return "", fmt.Errorf("%s:%d: unknown directive: %s", path, lineNo, directive)
		}
