		return nil, fmt.Errorf("could not find file %s in any of the loaded packages", abs)
	}
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, abs, data, 0)
	if err != nil {
		return nil, err
	}
	fileDir := filepath.Dir(abs)
	ownPkg := p.scanDir(fileDir)
	ownName := ""
	var ownSymbols map[string]string
