	}
	for _, spec := range f.Imports {
		rawPath := ""
		if spec.Path != nil {
			if uq, err := strconv.Unquote(spec.Path.Value); err == nil {
				rawPath = uq
			} else {
				rawPath = strings.Trim(spec.Path.Value, "\"`")
			}
		}
		alias := ""
		if spec.Name != nil {
			alias = spec.Name.Name
		}
		if alias == "_" {
			continue
		}
		if !strings.HasPrefix(rawPath, p.ModulePath+"/") {
			continue
		}
		sub := strings.TrimPrefix(rawPath, p.ModulePath+"/")
		pkgDir := filepath.Join(p.ModuleRoot, filepath.FromSlash(sub))
		pi := p.scanDir(pkgDir)
		addPkgErrs(pi)
		primary := pi.primaryName()
		syms := pi.byName[primary]
		if alias == "." {
			dotImports = append(dotImports, &importInfo{dot: true, symbols: syms})
		} else {
			sel := alias
			if sel == "" {
				sel = primary
			}
			if sel != "" {
				selectorImports[sel] = &importInfo{selector: sel, symbols: syms}
			}
		}
	}
	unresolved := map[*ast.Ident]bool{}
	for _, id := range f.Unresolved {
		unresolved[id] = true
	}
	var deps []string
	seenDep := map[string]bool{}
	addDep := func(path string) {
		if path != "" && !seenDep[path] {
			seenDep[path] = true
			deps = append(deps, filepath.Clean(path))
		}
	}
	ast.Inspect(f, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.SelectorExpr:
			if id, ok := node.X.(*ast.Ident); ok {
				if imp, ok := selectorImports[id.Name]; ok && imp.symbols != nil {
					if target, ok := imp.symbols[node.Sel.Name]; ok {
						addDep(target)
					}
				}
			}
			return true
		case *ast.Ident:
			if unresolved[node] {
				name := node.Name
				if ownSymbols != nil {
					if target, ok := ownSymbols[name]; ok && filepath.Clean(target) != abs {
						addDep(target)
						break_node := true
						_ = break_node
						return true
					}
				}
				for _, dot := range dotImports {
					if dot.symbols != nil {
						if target, ok := dot.symbols[name]; ok {
							addDep(target)
							break
						}
					}
				}
			}
			return true
		}
		return true
	})
	return &language.ParsedFile{
		AbsPath: abs, DisplayPath: p.RelPath(abs), Group: ownName, Loc: loc,
		Dependencies: deps, Errors: fileErrs,
	}, nil
}
