		if spec.Name != nil {
			alias = spec.Name.Name
		}
		if alias == "_" {
			continue
		}
		if !strings.HasPrefix(rawPath, p.ModulePath+"/") {
			continue
		}
		sub := strings.TrimPrefix(rawPath, p.ModulePath+"/")
		pkgDir := filepath.Join(p.ModuleRoot, filepath.FromSlash(sub))
		pi := p.scanDir(pkgDir)
		addPkgErrs(pi)
