						_ = break_node
						return true
					}
				}
				for _, dot := range dotImports {
					if dot.symbols != nil {
						if target, ok := dot.symbols[name]; ok {
							addDep(target)
							break
						}
					}
				}
			}
			return true
		}
		return true
	})
	return &language.ParsedFile{
		AbsPath: abs, DisplayPath: p.RelPath(abs), Group: ownName, Loc: loc,
		Dependencies: deps, Errors: fileErrs,
	}, nil
}
