func isFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

// token lexer for Rust (only as much as needed for mod/use scanning).
type rtoken struct {
	ident string // identifier text if ident, otherwise ""
	text  string
	isIdent bool
}

func lexRust(src string) []rtoken {
	rs := []rune(src)
	var toks []rtoken
	i := 0
	isStart := func(r rune) bool { return r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || r >= 128 }
	isPart := func(r rune) bool { return isStart(r) || (r >= '0' && r <= '9') }
	for i < len(rs) {
		c := rs[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		if c == '/' && i+1 < len(rs) && rs[i+1] == '/' {
			for i < len(rs) && rs[i] != '\n' { i++ }
			continue
		}
		if c == '/' && i+1 < len(rs) && rs[i+1] == '*' {
			depth := 1
			i += 2
			for i+1 < len(rs) && depth > 0 {
				if rs[i] == '/' && rs[i+1] == '*' { depth++; i += 2; continue }
				if rs[i] == '*' && rs[i+1] == '/' { depth--; i += 2; continue }
				i++
			}
			continue
		}
		// Raw string r#"..."# or r"..."
		if c == 'r' {
			j := i + 1
			for j < len(rs) && rs[j] == '#' { j++ }
			if j < len(rs) && rs[j] == '"' {
				hashes := strings.Repeat("#", j-(i+1))
				j++
				for j < len(rs) {
					if rs[j] == '"' && strings.HasPrefix(string(rs[j+1:]), hashes) {
						j += 1 + len([]rune(hashes))
						break
					}
					j++
				}
				toks = append(toks, rtoken{text: "\"\""})
				i = j
				continue
			}
		}
		if c == '"' {
			i++
			for i < len(rs) {
				if rs[i] == '\\' { i += 2; continue }
				if rs[i] == '"' { i++; break }
				i++
			}
			toks = append(toks, rtoken{text: "\"\""})
			continue
		}
		if c == '\'' {
			// Char literal forms: 'x'  '\n'  '\u{..}' ; lifetime 'a otherwise.
			if i+2 < len(rs) && rs[i+2] == '\'' && rs[i+1] != '\\' {
				toks = append(toks, rtoken{text: "' '"})
				i += 3
				continue
			}
			if i+3 < len(rs) && rs[i+1] == '\\' && rs[i+3] == '\'' {
				toks = append(toks, rtoken{text: "' '"})
				i += 4
				continue
			}
			// Lifetime: consume 'ident as one ident token.
			j := i + 1
			for j < len(rs) && isPart(rs[j]) { j++ }
			toks = append(toks, rtoken{ident: string(rs[i:j]), text: string(rs[i:j]), isIdent: true})
			i = j
			continue
		}
		if isStart(c) {
			j := i
			for j < len(rs) && isPart(rs[j]) { j++ }
			toks = append(toks, rtoken{ident: string(rs[i:j]), text: string(rs[i:j]), isIdent: true})
			i = j
			continue
		}
		if c == ':' && i+1 < len(rs) && rs[i+1] == ':' {
			toks = append(toks, rtoken{text: "::"})
			i += 2
			continue
		}
		toks = append(toks, rtoken{text: string(c)})
		i++
	}
	return toks
}

func extractMods(toks []rtoken) []string {
	var mods []string
	for i := 0; i+2 < len(toks); i++ {
		if toks[i].isIdent && toks[i].ident == "mod" && toks[i+1].isIdent && toks[i+2].text == ";" {
			mods = append(mods, toks[i+1].ident)
		}
	}
	return mods
}

// extractUses returns expanded use paths, each as segment slices.
func extractUses(toks []rtoken) [][]string {
	var paths [][]string
	for i := 0; i < len(toks); i++ {
		if !(toks[i].isIdent && toks[i].ident == "use") {
			continue
		}
		// Collect until ';' at brace depth 0 (use trees end with ';').
		var clause []rtoken
		j := i + 1
		for ; j < len(toks); j++ {
			if toks[j].text == ";" {
				break
			}
			clause = append(clause, toks[j])
		}
		text := clauseString(clause)
		for _, expanded := range expandUseBraces(text) {
			expanded = strings.TrimSpace(expanded)
			// Drop " as alias" at top level.
			if idx := strings.Index(expanded, " as "); idx >= 0 {
				expanded = strings.TrimSpace(expanded[:idx])
			}
			segs := splitUsePath(expanded)
			if len(segs) > 0 {
				paths = append(paths, segs)
			}
		}
		i = j
	}
	return paths
}

func clauseString(toks []rtoken) string {
	var b strings.Builder
	for _, t := range toks {
		if t.isIdent {
			// Reconstruct with spaces around idents so "as" detection works.
			b.WriteString(" ")
			b.WriteString(t.ident)
			b.WriteString(" ")
		} else {
			b.WriteString(t.text)
		}
	}
	return b.String()
}

func expandUseBraces(s string) []string {
	start := strings.Index(s, "{")
	if start < 0 {
		return []string{s}
	}
	depth := 0
	end := -1
	var commas []int
	for i := start; i < len(s); i++ {
		switch s[i] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				end = i
			}
		case ',':
			if depth == 1 {
				commas = append(commas, i)
			}
		}
		if end >= 0 { break }
	}
	if end < 0 {
		return []string{s}
	}
	var parts []string
	prev := start + 1
	for _, c := range commas { parts = append(parts, s[prev:c]); prev = c + 1 }
	parts = append(parts, s[prev:end])
	var out []string
	for _, part := range parts {
		out = append(out, expandUseBraces(s[:start]+part+s[end+1:])...)
	}
	return out
}

func splitUsePath(s string) []string {
	s = strings.TrimSpace(s)
	leading := strings.HasPrefix(s, "::")
	parts := strings.Split(s, "::")
	var out []string
	if leading {
		out = append(out, "")
	}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		out = append(out, p)
	}
	return out
}

type modNode struct {
	file     string
	path     []string
	children map[string]*modNode
}

func (p *Parser) modsOf(abs string) []string {
	if v, ok := p.parsedMods[abs]; ok {
		return v
	}
	data, err := os.ReadFile(abs)
	if err != nil {
		p.parsedMods[abs] = nil
		return nil
	}
	mods := extractMods(lexRust(string(data)))
	p.parsedMods[abs] = mods
	return mods
}

func resolveModFile(baseDir, name string) string {
	cand := filepath.Join(baseDir, name+".rs")
	if isFile(cand) {
		return cand
	}
	cand = filepath.Join(baseDir, name, "mod.rs")
	if isFile(cand) {
		return cand
	}
	return ""
}

func (p *Parser) buildTree(rootFile string) *modNode {
	if v, ok := p.treeCache[rootFile]; ok {
		return v
	}
	root := &modNode{file: rootFile, path: nil, children: map[string]*modNode{}}
	p.treeCache[rootFile] = root
	var build func(n *modNode, isRoot bool)
	seen := map[string]bool{}
	build = func(n *modNode, isRoot bool) {
		if seen[n.file] {
			return
		}
		seen[n.file] = true
		baseDir := filepath.Dir(n.file)
		if !isRoot && filepath.Base(n.file) != "mod.rs" {
			stem := strings.TrimSuffix(filepath.Base(n.file), filepath.Ext(n.file))
			baseDir = filepath.Join(baseDir, stem)
		}
		for _, name := range p.modsOf(n.file) {
			child := resolveModFile(baseDir, name)
			if child == "" {
				continue
			}
			cn := &modNode{file: child, path: append(append([]string(nil), n.path...), name), children: map[string]*modNode{}}
			n.children[name] = cn
		}
		for _, cn := range n.children {
			build(cn, false)
		}
	}
	build(root, true)
	return root
}

func findNode(root *modNode, path []string) *modNode {
	n := root
	for _, seg := range path {
		c, ok := n.children[seg]
		if !ok {
			return nil
		}
		n = c
	}
	return n
}

func modulePathOf(abs, rootFile string) []string {
	if abs == rootFile {
		return nil
	}
	dir := filepath.Dir(rootFile)
	rel, err := filepath.Rel(dir, abs)
	if err != nil {
		return nil
	}
	rel = filepath.ToSlash(rel)
	rel = strings.TrimSuffix(rel, ".rs")
	parts := strings.Split(rel, "/")
	if len(parts) > 0 && parts[len(parts)-1] == "mod" {
		parts = parts[:len(parts)-1]
	}
	var out []string
	for _, p := range parts {
		if p != "." && p != "" {
			out = append(out, p)
		}
	}
	return out
}

func (p *Parser) crateRootFile(abs string, cargo cargoInfo) string {
	srcDir := filepath.Join(cargo.rootDir, "src")
	// Bias to the file the parser was created for when it is a bin/main/lib root.
	if p.firstFile != "" {
		rel, err := filepath.Rel(srcDir, p.firstFile)
		if err == nil && !strings.HasPrefix(rel, "..") {
			parts := strings.Split(filepath.ToSlash(rel), "/")
			if parts[0] == "bin" || rel == "main.rs" || rel == "lib.rs" {
				// For src/bin/<tool>/... the root is src/bin/<tool>/main.rs — approximate with firstFile chain.
				if parts[0] == "bin" && len(parts) > 2 {
					cand := filepath.Join(srcDir, "bin", parts[1], "main.rs")
					if isFile(cand) {
						return cand
					}
				}
				return p.firstFile
			}
		}
	}
	// If the parsed file itself is under src/bin, it may be its own bin root.
	if rel, err := filepath.Rel(srcDir, abs); err == nil && !strings.HasPrefix(rel, "..") {
		parts := strings.Split(filepath.ToSlash(rel), "/")
		if parts[0] == "bin" {
			if len(parts) == 2 {
				return abs
			}
			cand := filepath.Join(srcDir, "bin", parts[1], "main.rs")
			if isFile(cand) {
				return cand
			}
			return abs
		}
	}
	if cand := filepath.Join(srcDir, "lib.rs"); isFile(cand) {
		return cand
	}
	if cand := filepath.Join(srcDir, "main.rs"); isFile(cand) {
		return cand
	}
	return abs
}

type cargoName struct{ Name string }

func (p *Parser) ParseFile(abs string) (*language.ParsedFile, error) {
	abs = filepath.Clean(abs)
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	fileDir := filepath.Dir(abs)
	cargo := p.cargoFor(fileDir)
	if !cargo.found {
		var c *cargoName
		_ = c.Name // panics like the original when no Cargo.toml exists
	}
	toks := lexRust(string(data))
	var deps []string
	var errs []string
	seen := map[string]bool{}
	addDep := func(d string) {
		d = filepath.Clean(d)
		if !seen[d] {
			seen[d] = true
			deps = append(deps, d)
		}
	}
	// Interleave mod and use statements in source order by scanning token indexes.
	rootFile := p.crateRootFile(abs, cargo)
	tree := p.buildTree(rootFile)
	myPath := modulePathOf(abs, rootFile)
	modsByIndex := map[int]string{}
	for i := 0; i+2 < len(toks); i++ {
		if toks[i].isIdent && toks[i].ident == "mod" && toks[i+1].isIdent && toks[i+2].text == ";" {
			modsByIndex[i] = toks[i+1].ident
		}
	}
	usesByIndex := map[int][][]string{}
	{
		// Reuse extractUses logic but keyed by index: simpler to compute all and match by walking again.
		all := extractUses(toks)
		_ = all
	}
	// Single pass collecting events in order.
	type ev struct {
		isMod bool
		name  string
		use   []string
	}
	var events []ev
	usePaths := extractUses(toks)
	// We need source order across mod/use. Extract with indexes:
	events = events[:0]
	{
		// Walk token stream, recording mods and uses in order.
		ui := 0
		_ = ui
		for i := 0; i < len(toks); i++ {
			if name, ok := modsByIndex[i]; ok {
				events = append(events, ev{isMod: true, name: name})
			}
			if toks[i].isIdent && toks[i].ident == "use" {
				// Find the paths corresponding to this use by re-expanding this clause only.
				var clause []rtoken
				j := i + 1
				for ; j < len(toks); j++ {
					if toks[j].text == ";" { break }
					clause = append(clause, toks[j])
				}
				text := clauseString(clause)
				for _, expanded := range expandUseBraces(text) {
					expanded = strings.TrimSpace(expanded)
					if idx := strings.Index(expanded, " as "); idx >= 0 {
						expanded = strings.TrimSpace(expanded[:idx])
					}
					segs := splitUsePath(expanded)
					if len(segs) > 0 {
						events = append(events, ev{use: segs})
					}
				}
				i = j
			}
		}
		_ = usePaths
	}
	for _, e := range events {
		if e.isMod {
			child := resolveModFile(fileDir, e.name)
			if child == "" {
				errs = append(errs, fmt.Sprintf("could not find mod %s while looking in dir %s", e.name, fileDir))
			} else {
				addDep(child)
			}
			continue
		}
		segs := e.use
		if len(segs) == 0 {
			continue
		}
		finalName := segs[len(segs)-1]
		if cargo.err != "" {
			errs = append(errs, fmt.Sprintf("error resolving use statement for name %s: %s", finalName, cargo.err))
			continue
		}
		dep, errStr, external := p.resolveUse(tree, rootFile, myPath, segs, cargo)
		if external {
			continue
		}
		if errStr != "" {
			errs = append(errs, errStr)
			continue
		}
		if dep != "" {
			addDep(dep)
		}
	}
	group := ""
	if cargo.valid {
		group = cargo.name
	}
	return &language.ParsedFile{
		AbsPath: abs, DisplayPath: p.RelPath(abs), Group: group, Loc: loc,
		Dependencies: deps, Errors: errs,
	}, nil
}

func (p *Parser) resolveUse(tree *modNode, rootFile string, myPath []string, segs []string, cargo cargoInfo) (string, string, bool) {
	finalName := segs[len(segs)-1]
	fail := func() (string, string, bool) {
		return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", finalName), false
	}
	var basePath []string
	var rest []string
	crateName := strings.ReplaceAll(cargo.name, "-", "_")
	i := 0
	leading := false
	if len(segs) > 0 && segs[0] == "" {
		leading = true
		i = 1
	}
	if i >= len(segs) {
		return "", "", true
	}
	first := segs[i]
	switch {
	case first == "crate":
		basePath = nil
		rest = segs[i+1:]
	case first == "self":
		basePath = myPath
		rest = segs[i+1:]
	case first == "super":
		// Count consecutive supers.
		ups := 0
		j := i
		for j < len(segs) && segs[j] == "super" {
			ups++
			j++
		}
		if ups > len(myPath) {
			return fail()
		}
		basePath = myPath[:len(myPath)-ups]
		rest = segs[j:]
	case crateName != "" && first == crateName:
		// If this file belongs to a binary crate while a lib exists, the
		// package name refers to the library — treat as external.
		srcDir := filepath.Join(cargo.rootDir, "src")
		if filepath.Base(rootFile) == "main.rs" || strings.Contains(filepath.ToSlash(rootFile), "/src/bin/") {
			if isFile(filepath.Join(srcDir, "lib.rs")) {
				return "", "", true
			}
		}
		basePath = nil
		rest = segs[i+1:]
	case leading:
		// Leading ::name refers to an external crate.
		return "", "", true
	default:
		// Relative path: try as a path from the current module, then from crate root.
		// Determine if it could be local at all.
		if findNode(tree, append(append([]string(nil), myPath...), first)) != nil {
			basePath = myPath
			rest = segs[i:]
		} else if findNode(tree, []string{first}) != nil {
			basePath = nil
			rest = segs[i:]
		} else {
			return "", "", true
		}
	}
	base := findNode(tree, basePath)
	if base == nil {
		// Current module may not be in the tree (its file was not reached
		// via mod declarations). Synthesise resolution by path against the tree.
		return fail()
	}
	if len(rest) == 0 {
		return base.file, "", false
	}
	// Navigate rest as module segments; the last segment may be an item.
	node := base
	for k, seg := range rest {
		if seg == "*" {
			return node.file, "", false
		}
		child, ok := node.children[seg]
		if !ok {
			if k == len(rest)-1 {
				// Final segment is an item inside node.
				return node.file, "", false
			}
			return fail()
		}
		node = child
	}
	return node.file, "", false
}
EOF
gofmt -w internal/rust/parser.go"}

actions.command:
cat > internal/rust/parser.go <<'EOF'
package rust

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"deptree/internal/graph"
	"deptree/internal/language"

	"github.com/BurntSushi/toml"
)

type cargoInfo struct {
	rootDir string
	name    string
	found   bool
	valid   bool
	err     string
}

type Parser struct {
	firstFile string
	cargoCache map[string]cargoInfo
	treeCache map[string]*modNode
	parsedMods map[string][]string // abs -> mod names declared
}

func NewParser(firstFile string) *Parser {
	abs, _ := filepath.Abs(firstFile)
	return &Parser{firstFile: filepath.Clean(abs), cargoCache: map[string]cargoInfo{}, treeCache: map[string]*modNode{}, parsedMods: map[string][]string{}}
}

func (p *Parser) cargoFor(fileDir string) cargoInfo {
	if v, ok := p.cargoCache[fileDir]; ok {
		return v
	}
	var out cargoInfo
	for d := fileDir; ; d = filepath.Dir(d) {
		path := filepath.Join(d, "Cargo.toml")
		if info, err := os.Stat(path); err == nil && !info.IsDir() {
			out.rootDir = d
			out.found = true
			data, err := os.ReadFile(path)
			if err != nil {
				out.err = err.Error()
				break
			}
			var cfg struct {
				Package struct {
					Name string `toml:"name"`
				} `toml:"package"`
			}
			if err := toml.Unmarshal(data, &cfg); err != nil {
				out.err = err.Error()
			} else {
				out.valid = true
				out.name = cfg.Package.Name
			}
			break
		}
		if filepath.Dir(d) == d {
			break
		}
	}
	p.cargoCache[fileDir] = out
	return out
}

func (p *Parser) RelPath(abs string) string {
	abs = filepath.Clean(abs)
	c := p.cargoFor(filepath.Dir(abs))
	if !c.found || !c.valid {
		return ""
	}
	rel, err := filepath.Rel(c.rootDir, abs)
	if err != nil {
		return ""
	}
	return filepath.ToSlash(rel)
}

func isFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

// token lexer for Rust (only as much as needed for mod/use scanning).
type rtoken struct {
	ident string // identifier text if ident, otherwise ""
	text  string
	isIdent bool
}

func lexRust(src string) []rtoken {
	rs := []rune(src)
	var toks []rtoken
	i := 0
	isStart := func(r rune) bool { return r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || r >= 128 }
	isPart := func(r rune) bool { return isStart(r) || (r >= '0' && r <= '9') }
	for i < len(rs) {
		c := rs[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		if c == '/' && i+1 < len(rs) && rs[i+1] == '/' {
			for i < len(rs) && rs[i] != '\n' { i++ }
			continue
		}
		if c == '/' && i+1 < len(rs) && rs[i+1] == '*' {
			depth := 1
			i += 2
			for i+1 < len(rs) && depth > 0 {
				if rs[i] == '/' && rs[i+1] == '*' { depth++; i += 2; continue }
				if rs[i] == '*' && rs[i+1] == '/' { depth--; i += 2; continue }
				i++
			}
			continue
		}
		// Raw string r#"..."# or r"..."
		if c == 'r' {
			j := i + 1
			for j < len(rs) && rs[j] == '#' { j++ }
			if j < len(rs) && rs[j] == '"' {
				hashes := strings.Repeat("#", j-(i+1))
				j++
				for j < len(rs) {
					if rs[j] == '"' && strings.HasPrefix(string(rs[j+1:]), hashes) {
						j += 1 + len([]rune(hashes))
						break
					}
					j++
				}
				toks = append(toks, rtoken{text: "\"\""})
				i = j
				continue
			}
		}
		if c == '"' {
			i++
			for i < len(rs) {
				if rs[i] == '\\' { i += 2; continue }
				if rs[i] == '"' { i++; break }
				i++
			}
			toks = append(toks, rtoken{text: "\"\""})
			continue
		}
		if c == '\'' {
			// Char literal forms: 'x'  '\n'  '\u{..}' ; lifetime 'a otherwise.
			if i+2 < len(rs) && rs[i+2] == '\'' && rs[i+1] != '\\' {
				toks = append(toks, rtoken{text: "' '"})
				i += 3
				continue
			}
			if i+3 < len(rs) && rs[i+1] == '\\' && rs[i+3] == '\'' {
				toks = append(toks, rtoken{text: "' '"})
				i += 4
				continue
			}
			// Lifetime: consume 'ident as one ident token.
			j := i + 1
			for j < len(rs) && isPart(rs[j]) { j++ }
			toks = append(toks, rtoken{ident: string(rs[i:j]), text: string(rs[i:j]), isIdent: true})
			i = j
			continue
		}
		if isStart(c) {
			j := i
			for j < len(rs) && isPart(rs[j]) { j++ }
			toks = append(toks, rtoken{ident: string(rs[i:j]), text: string(rs[i:j]), isIdent: true})
			i = j
			continue
		}
		if c == ':' && i+1 < len(rs) && rs[i+1] == ':' {
			toks = append(toks, rtoken{text: "::"})
			i += 2
			continue
		}
		toks = append(toks, rtoken{text: string(c)})
		i++
	}
	return toks
}

func extractMods(toks []rtoken) []string {
	var mods []string
	for i := 0; i+2 < len(toks); i++ {
		if toks[i].isIdent && toks[i].ident == "mod" && toks[i+1].isIdent && toks[i+2].text == ";" {
			mods = append(mods, toks[i+1].ident)
		}
	}
	return mods
}

// extractUses returns expanded use paths, each as segment slices.
func extractUses(toks []rtoken) [][]string {
	var paths [][]string
	for i := 0; i < len(toks); i++ {
		if !(toks[i].isIdent && toks[i].ident == "use") {
			continue
		}
		// Collect until ';' at brace depth 0 (use trees end with ';').
		var clause []rtoken
		j := i + 1
		for ; j < len(toks); j++ {
			if toks[j].text == ";" {
				break
			}
			clause = append(clause, toks[j])
		}
		text := clauseString(clause)
		for _, expanded := range expandUseBraces(text) {
			expanded = strings.TrimSpace(expanded)
			// Drop " as alias" at top level.
			if idx := strings.Index(expanded, " as "); idx >= 0 {
				expanded = strings.TrimSpace(expanded[:idx])
			}
			segs := splitUsePath(expanded)
			if len(segs) > 0 {
				paths = append(paths, segs)
			}
		}
		i = j
	}
	return paths
}

func clauseString(toks []rtoken) string {
	var b strings.Builder
	for _, t := range toks {
		if t.isIdent {
			// Reconstruct with spaces around idents so "as" detection works.
			b.WriteString(" ")
			b.WriteString(t.ident)
			b.WriteString(" ")
		} else {
			b.WriteString(t.text)
		}
	}
	return b.String()
}

func expandUseBraces(s string) []string {
	start := strings.Index(s, "{")
	if start < 0 {
		return []string{s}
	}
	depth := 0
	end := -1
	var commas []int
	for i := start; i < len(s); i++ {
		switch s[i] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				end = i
			}
		case ',':
			if depth == 1 {
				commas = append(commas, i)
			}
		}
		if end >= 0 { break }
	}
	if end < 0 {
		return []string{s}
	}
	var parts []string
	prev := start + 1
	for _, c := range commas { parts = append(parts, s[prev:c]); prev = c + 1 }
	parts = append(parts, s[prev:end])
	var out []string
	for _, part := range parts {
		out = append(out, expandUseBraces(s[:start]+part+s[end+1:])...)
	}
	return out
}

func splitUsePath(s string) []string {
	s = strings.TrimSpace(s)
	leading := strings.HasPrefix(s, "::")
	parts := strings.Split(s, "::")
	var out []string
	if leading {
		out = append(out, "")
	}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		out = append(out, p)
	}
	return out
}

type modNode struct {
	file     string
	path     []string
	children map[string]*modNode
}

func (p *Parser) modsOf(abs string) []string {
	if v, ok := p.parsedMods[abs]; ok {
		return v
	}
	data, err := os.ReadFile(abs)
	if err != nil {
		p.parsedMods[abs] = nil
		return nil
	}
	mods := extractMods(lexRust(string(data)))
	p.parsedMods[abs] = mods
	return mods
}

func resolveModFile(baseDir, name string) string {
	cand := filepath.Join(baseDir, name+".rs")
	if isFile(cand) {
		return cand
	}
	cand = filepath.Join(baseDir, name, "mod.rs")
	if isFile(cand) {
		return cand
	}
	return ""
}

func (p *Parser) buildTree(rootFile string) *modNode {
	if v, ok := p.treeCache[rootFile]; ok {
		return v
	}
	root := &modNode{file: rootFile, path: nil, children: map[string]*modNode{}}
	p.treeCache[rootFile] = root
	var build func(n *modNode, isRoot bool)
	seen := map[string]bool{}
	build = func(n *modNode, isRoot bool) {
		if seen[n.file] {
			return
		}
		seen[n.file] = true
		baseDir := filepath.Dir(n.file)
		if !isRoot && filepath.Base(n.file) != "mod.rs" {
			stem := strings.TrimSuffix(filepath.Base(n.file), filepath.Ext(n.file))
			baseDir = filepath.Join(baseDir, stem)
		}
		for _, name := range p.modsOf(n.file) {
			child := resolveModFile(baseDir, name)
			if child == "" {
				continue
			}
			cn := &modNode{file: child, path: append(append([]string(nil), n.path...), name), children: map[string]*modNode{}}
			n.children[name] = cn
		}
		for _, cn := range n.children {
			build(cn, false)
		}
	}
	build(root, true)
	return root
}

func findNode(root *modNode, path []string) *modNode {
	n := root
	for _, seg := range path {
		c, ok := n.children[seg]
		if !ok {
			return nil
		}
		n = c
	}
	return n
}

func modulePathOf(abs, rootFile string) []string {
	if abs == rootFile {
		return nil
	}
	dir := filepath.Dir(rootFile)
	rel, err := filepath.Rel(dir, abs)
	if err != nil {
		return nil
	}
	rel = filepath.ToSlash(rel)
	rel = strings.TrimSuffix(rel, ".rs")
	parts := strings.Split(rel, "/")
	if len(parts) > 0 && parts[len(parts)-1] == "mod" {
		parts = parts[:len(parts)-1]
	}
	var out []string
	for _, p := range parts {
		if p != "." && p != "" {
			out = append(out, p)
		}
	}
	return out
}

func (p *Parser) crateRootFile(abs string, cargo cargoInfo) string {
	srcDir := filepath.Join(cargo.rootDir, "src")
	// Bias to the file the parser was created for when it is a bin/main/lib root.
	if p.firstFile != "" {
		rel, err := filepath.Rel(srcDir, p.firstFile)
		if err == nil && !strings.HasPrefix(rel, "..") {
			parts := strings.Split(filepath.ToSlash(rel), "/")
			if parts[0] == "bin" || rel == "main.rs" || rel == "lib.rs" {
				// For src/bin/<tool>/... the root is src/bin/<tool>/main.rs — approximate with firstFile chain.
				if parts[0] == "bin" && len(parts) > 2 {
					cand := filepath.Join(srcDir, "bin", parts[1], "main.rs")
					if isFile(cand) {
						return cand
					}
				}
				return p.firstFile
			}
		}
	}
	// If the parsed file itself is under src/bin, it may be its own bin root.
	if rel, err := filepath.Rel(srcDir, abs); err == nil && !strings.HasPrefix(rel, "..") {
		parts := strings.Split(filepath.ToSlash(rel), "/")
		if parts[0] == "bin" {
			if len(parts) == 2 {
				return abs
			}
			cand := filepath.Join(srcDir, "bin", parts[1], "main.rs")
			if isFile(cand) {
				return cand
			}
			return abs
		}
	}
	if cand := filepath.Join(srcDir, "lib.rs"); isFile(cand) {
		return cand
	}
	if cand := filepath.Join(srcDir, "main.rs"); isFile(cand) {
		return cand
	}
	return abs
}

type cargoName struct{ Name string }

func (p *Parser) ParseFile(abs string) (*language.ParsedFile, error) {
	abs = filepath.Clean(abs)
	data, loc, err := graph.ReadFileLoc(abs)
	if err != nil {
		return nil, err
	}
	fileDir := filepath.Dir(abs)
	cargo := p.cargoFor(fileDir)
	if !cargo.found {
		var c *cargoName
		_ = c.Name // panics like the original when no Cargo.toml exists
	}
	toks := lexRust(string(data))
	var deps []string
	var errs []string
	seen := map[string]bool{}
	addDep := func(d string) {
		d = filepath.Clean(d)
		if !seen[d] {
			seen[d] = true
			deps = append(deps, d)
		}
	}
	// Interleave mod and use statements in source order by scanning token indexes.
	rootFile := p.crateRootFile(abs, cargo)
	tree := p.buildTree(rootFile)
	myPath := modulePathOf(abs, rootFile)
	modsByIndex := map[int]string{}
	for i := 0; i+2 < len(toks); i++ {
		if toks[i].isIdent && toks[i].ident == "mod" && toks[i+1].isIdent && toks[i+2].text == ";" {
			modsByIndex[i] = toks[i+1].ident
		}
	}
	usesByIndex := map[int][][]string{}
	{
		// Reuse extractUses logic but keyed by index: simpler to compute all and match by walking again.
		all := extractUses(toks)
		_ = all
	}
	// Single pass collecting events in order.
	type ev struct {
		isMod bool
		name  string
		use   []string
	}
	var events []ev
	usePaths := extractUses(toks)
	// We need source order across mod/use. Extract with indexes:
	events = events[:0]
	{
		// Walk token stream, recording mods and uses in order.
		ui := 0
		_ = ui
		for i := 0; i < len(toks); i++ {
			if name, ok := modsByIndex[i]; ok {
				events = append(events, ev{isMod: true, name: name})
			}
			if toks[i].isIdent && toks[i].ident == "use" {
				// Find the paths corresponding to this use by re-expanding this clause only.
				var clause []rtoken
				j := i + 1
				for ; j < len(toks); j++ {
					if toks[j].text == ";" { break }
					clause = append(clause, toks[j])
				}
				text := clauseString(clause)
				for _, expanded := range expandUseBraces(text) {
					expanded = strings.TrimSpace(expanded)
					if idx := strings.Index(expanded, " as "); idx >= 0 {
						expanded = strings.TrimSpace(expanded[:idx])
					}
					segs := splitUsePath(expanded)
					if len(segs) > 0 {
						events = append(events, ev{use: segs})
					}
				}
				i = j
			}
		}
		_ = usePaths
	}
	for _, e := range events {
		if e.isMod {
			child := resolveModFile(fileDir, e.name)
			if child == "" {
				errs = append(errs, fmt.Sprintf("could not find mod %s while looking in dir %s", e.name, fileDir))
			} else {
				addDep(child)
			}
			continue
		}
		segs := e.use
		if len(segs) == 0 {
			continue
		}
		finalName := segs[len(segs)-1]
		if cargo.err != "" {
			errs = append(errs, fmt.Sprintf("error resolving use statement for name %s: %s", finalName, cargo.err))
			continue
		}
		dep, errStr, external := p.resolveUse(tree, rootFile, myPath, segs, cargo)
		if external {
			continue
		}
		if errStr != "" {
			errs = append(errs, errStr)
			continue
		}
		if dep != "" {
			addDep(dep)
		}
	}
	group := ""
	if cargo.valid {
		group = cargo.name
	}
	return &language.ParsedFile{
		AbsPath: abs, DisplayPath: p.RelPath(abs), Group: group, Loc: loc,
		Dependencies: deps, Errors: errs,
	}, nil
}

func (p *Parser) resolveUse(tree *modNode, rootFile string, myPath []string, segs []string, cargo cargoInfo) (string, string, bool) {
	finalName := segs[len(segs)-1]
	fail := func() (string, string, bool) {
		return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", finalName), false
	}
	var basePath []string
	var rest []string
	crateName := strings.ReplaceAll(cargo.name, "-", "_")
	i := 0
	leading := false
	if len(segs) > 0 && segs[0] == "" {
		leading = true
		i = 1
	}
	if i >= len(segs) {
		return "", "", true
	}
	first := segs[i]
	switch {
	case first == "crate":
		basePath = nil
		rest = segs[i+1:]
	case first == "self":
		basePath = myPath
		rest = segs[i+1:]
	case first == "super":
		// Count consecutive supers.
		ups := 0
		j := i
		for j < len(segs) && segs[j] == "super" {
			ups++
			j++
		}
		if ups > len(myPath) {
			return fail()
		}
		basePath = myPath[:len(myPath)-ups]
		rest = segs[j:]
	case crateName != "" && first == crateName:
		// If this file belongs to a binary crate while a lib exists, the
		// package name refers to the library — treat as external.
		srcDir := filepath.Join(cargo.rootDir, "src")
		if filepath.Base(rootFile) == "main.rs" || strings.Contains(filepath.ToSlash(rootFile), "/src/bin/") {
			if isFile(filepath.Join(srcDir, "lib.rs")) {
				return "", "", true
			}
		}
		basePath = nil
		rest = segs[i+1:]
	case leading:
		// Leading ::name refers to an external crate.
		return "", "", true
	default:
		// Relative path: try as a path from the current module, then from crate root.
		// Determine if it could be local at all.
		if findNode(tree, append(append([]string(nil), myPath...), first)) != nil {
			basePath = myPath
			rest = segs[i:]
		} else if findNode(tree, []string{first}) != nil {
			basePath = nil
			rest = segs[i:]
		} else {
			return "", "", true
		}
	}
	base := findNode(tree, basePath)
	if base == nil {
		// Current module may not be in the tree (its file was not reached
		// via mod declarations). Synthesise resolution by path against the tree.
		return fail()
	}
	if len(rest) == 0 {
		return base.file, "", false
	}
	// Navigate rest as module segments; the last segment may be an item.
	node := base
	for k, seg := range rest {
		if seg == "*" {
			return node.file, "", false
		}
		child, ok := node.children[seg]
		if !ok {
			if k == len(rest)-1 {
				// Final segment is an item inside node.
				return node.file, "", false
			}
			return fail()
		}
		node = child
	}
	return node.file, "", false
}
