package tree

import (
	"strings"

	"deptree/internal/graph"
)

type Node struct {
	Graph    *graph.Node
	Children []*Node
}

func Build(g *graph.Graph, rootAbs string) (*Node, [][]string) {
	root := g.ByAbs[rootAbs]
	if root == nil {
		return nil, [][]string{}
	}
	var cycles [][]string
	seenCycle := map[string]bool{}
	var build func(n *graph.Node, ancestors []string) *Node
	build = func(n *graph.Node, ancestors []string) *Node {
		out := &Node{Graph: n}
		for _, depAbs := range n.Dependencies {
			// Cycle?
			idx := -1
			for i, a := range ancestors {
				if a == depAbs {
					idx = i
					break
				}
			}
			if idx >= 0 {
				var cyc []string
				for _, a := range ancestors[idx:] {
					cyc = append(cyc, g.ByAbs[a].DisplayPath)
				}
				cyc = append(cyc, g.ByAbs[depAbs].DisplayPath)
				key := strings.Join(cyc, "\x00")
				if !seenCycle[key] {
					seenCycle[key] = true
					cycles = append(cycles, cyc)
				}
				continue
			}
			child := g.ByAbs[depAbs]
			if child == nil {
				continue
			}
			out.Children = append(out.Children, build(child, append(append([]string(nil), ancestors...), depAbs)))
		}
		return out
	}
	rootNode := build(root, []string{rootAbs})
	if cycles == nil {
		cycles = [][]string{}
	}
	return rootNode, cycles
}

func ToMap(root *Node) map[string]interface{} {
	if root == nil {
		return map[string]interface{}{}
	}
	return map[string]interface{}{root.Graph.DisplayPath: nodeValue(root)}
}

func nodeValue(n *Node) interface{} {
	if len(n.Children) == 0 {
		return nil
	}
	m := make(map[string]interface{}, len(n.Children))
	for _, c := range n.Children {
		m[c.Graph.DisplayPath] = nodeValue(c)
	}
	return m
}

type Output struct {
	Tree                 map[string]interface{} `json:"tree"`
	CircularDependencies [][]string             `json:"circularDependencies"`
	Errors               map[string][]string    `json:"errors"`
}

func JSONOutput(g *graph.Graph, rootAbs string) Output {
	rootNode, cycles := Build(g, rootAbs)
	errs := map[string][]string{}
	for _, n := range g.Nodes {
		if len(n.Errors) > 0 {
			errs[n.DisplayPath] = n.Errors
		}
	}
	return Output{Tree: ToMap(rootNode), CircularDependencies: cycles, Errors: errs}
}
