package check

import (
	"errors"
	"strings"

	"deptree/internal/globutil"
	"deptree/internal/graph"
)

func expandOne(s string, aliases map[string][]string) []string {
	if v, ok := aliases[s]; ok {
		return v
	}
	return []string{s}
}

func expandList(list []string, aliases map[string][]string) []string {
	var out []string
	for _, s := range list {
		out = append(out, expandOne(s, aliases)...)
	}
	return out
}

func matchesAny(patterns []string, path string) (bool, error) {
	for _, p := range patterns {
		ok, err := globutil.Match(p, path)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}
	return false, nil
}

type violation struct {
	from, to, reason string
}

func Evaluate(g *graph.Graph, cfg Config) error {
	var violations []violation
	for _, node := range g.Nodes {
		for _, depAbs := range node.Dependencies {
			dep := g.ByAbs[depAbs]
			if dep == nil {
				continue
			}
			from := node.DisplayPath
			to := dep.DisplayPath
			violated := false
			reason := ""
			// Allow (white list): first matching from-pattern in map order wins.
			for pattern, entries := range cfg.Allow {
				ok, err := globutil.Match(pattern, from)
				if err != nil {
					return err
				}
				if !ok {
					continue
				}
				patterns := expandList(entries.To, cfg.Aliases)
				allowed, err := matchesAny(patterns, to)
				if err != nil {
					return err
				}
