package entropy

import (
	"encoding/json"
	"path/filepath"
	"strings"

	"deptree/internal/graph"
)

type Node struct {
	ID           uint32   `json:"id"`
	IsEntrypoint bool     `json:"isEntrypoint"`
	FileName     string   `json:"fileName"`
	PathBuf      []string `json:"pathBuf"`
	Group        string   `json:"group,omitempty"`
	DirName      string   `json:"dirName"`
	Loc          int      `json:"loc"`
	Size         int      `json:"size"`
}

type Link struct {
	From     uint32 `json:"from"`
	To       uint32 `json:"to"`
	IsCyclic bool   `json:"isCyclic"`
}

type Data struct {
	Nodes     []Node `json:"nodes"`
	Links     []Link `json:"links"`
	EnableGui bool   `json:"enableGui"`
}

func dirName(display string) string {
	if display == "" {
		return "./"
	}
	idx := strings.LastIndex(display, "/")
	if idx < 0 {
		return "./"
	}
	return display[:idx+1]
}

func Build(g *graph.Graph, entrypoints []string, enableGui bool) Data {
	data := Data{Nodes: []Node{}, Links: []Link{}, EnableGui: enableGui}
	singleEntry := ""
	if len(entrypoints) == 1 {
		singleEntry = filepath.Clean(entrypoints[0])
	}
	for _, n := range g.Nodes {
		size := 0
		if n.Loc > 0 {
			size = 10
		}
		data.Nodes = append(data.Nodes, Node{
			ID:           n.ID(),
			IsEntrypoint: singleEntry != "" && n.AbsPath == singleEntry,
			FileName:     filepath.Base(n.AbsPath),
			PathBuf:      strings.Split(n.AbsPath, "/"),
			Group:        n.Group,
			DirName:      dirName(n.DisplayPath),
			Loc:          n.Loc,
			Size:         size,
		})
	}
	cyclic := cyclicEdges(g, entrypoints)
	var plain, cyc []Link
	for _, n := range g.Nodes {
		for _, depAbs := range n.Dependencies {
			dep := g.ByAbs[depAbs]
			if dep == nil {
				continue
			}
			isCyc := cyclic[n.AbsPath+"->"+depAbs]
			link := Link{From: n.ID(), To: dep.ID(), IsCyclic: isCyc}
			if isCyc {
				cyc = append(cyc, link)
			} else {
				plain = append(plain, link)
			}
		}
	}
	data.Links = append(plain, cyc...)
	return data
}

func cyclicEdges(g *graph.Graph, entrypoints []string) map[string]bool {
	out := map[string]bool{}
	visited := map[string]bool{}
	var stack []string
	onStack := map[string]bool{}
	var dfs func(abs string)
	dfs = func(abs string) {
		visited[abs] = true
		stack = append(stack, abs)
		onStack[abs] = true
		node := g.ByAbs[abs]
		if node != nil {
			for _, dep := range node.Dependencies {
				if onStack[dep] {
					out[abs+"->"+dep] = true
				} else if !visited[dep] {
					dfs(dep)
				}
			}
		}
		stack = stack[:len(stack)-1]
		delete(onStack, abs)
	}
	for _, e := range entrypoints {
		e = filepath.Clean(e)
		if g.ByAbs[e] != nil && !visited[e] {
			dfs(e)
		}
	}
	for _, n := range g.Nodes {
		if !visited[n.AbsPath] {
			dfs(n.AbsPath)
		}
	}
	return out
}

