	flagJsWorkspaces                bool
	flagPythonExcludeConditional    bool
	flagOnly                        []string
	flagExclude                     []string
)

const rootLong = `
      ____         _ __       _
     |  _ \   ___ |  _ \    _| |_  _ __  ___   ___
     | | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
     | |_| ||  __/| .__/     | |  | |  |  __/|  __/
     |____/  \__| |_|        | \__|_|   \___| \___|`

func newRootCmd() *cobra.Command {
	rootCmd := &cobra.Command{
		Use:   "dep-tree",
		Long:  rootLong,
		Version: "v0.23.4",
		Example: "$ dep-tree src/index.ts\n$ dep-tree entropy src/index.ts\n$ dep-tree tree package/main.py --unwrap-exports\n$ dep-tree check",
		SilenceUsage: true,
		Args: cobra.ArbitraryArgs,
	}
	rootCmd.CompletionOptions.HiddenDefaultCmd = true
	pf := rootCmd.PersistentFlags()
	pf.SortFlags = false
	pf.StringVarP(&cfgFile, "config", "c", "", "path to dep-tree's config file. (default .dep-tree.yml)")
	pf.BoolVar(&flagUnwrapExports, "unwrap-exports", false, "trace re-exported symbols to the file where they are declared. (default false)")
	pf.BoolVar(&flagJsTsConfigPaths, "js-tsconfig-paths", true, "follow the tsconfig.json paths while resolving imports.")
	pf.BoolVar(&flagJsWorkspaces, "js-workspaces", true, "take the workspaces attribute in the root package.json into account for resolving paths.")
	pf.BoolVar(&flagPythonExcludeConditional, "python-exclude-conditional-imports", false, "exclude imports wrapped inside if or try statements. (default false)")
	pf.StringArrayVar(&flagOnly, "only", nil, "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.")
	pf.StringArrayVar(&flagExclude, "exclude", nil, "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.")

	rootCmd.AddGroup(
		&cobra.Group{ID: "visualize", Title: "Visualize your dependencies graphically"},
		&cobra.Group{ID: "check", Title: "Check your dependencies against your own rules"},
		&cobra.Group{ID: "explain", Title: "Display what are the dependencies between two portions of code"},
	)
	rootCmd.AddCommand(newEntropyCmd())
	rootCmd.AddCommand(newTreeCmd())
	rootCmd.AddCommand(newCheckCmd())
	rootCmd.AddCommand(newExplainCmd())
	rootCmd.AddCommand(newConfigCmd())
	return rootCmd
}

func prelimHelpChanged(args []string) bool {
	var cfg string
	var b1, b2, b3, b4, help bool
	var arr1, arr2 []string
	fs := pflag.NewFlagSet("prelim", pflag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.StringVarP(&cfg, "config", "c", "", "")
	fs.BoolVar(&b1, "unwrap-exports", false, "")
	fs.BoolVar(&b2, "js-tsconfig-paths", true, "")
	fs.BoolVar(&b3, "js-workspaces", true, "")
	fs.BoolVar(&b4, "python-exclude-conditional-imports", false, "")
	fs.StringArrayVar(&arr1, "only", nil, "")
	fs.StringArrayVar(&arr2, "exclude", nil, "")
	fs.BoolVarP(&help, "help", "h", false, "")
	_ = fs.Parse(args)
	f := fs.Lookup("help")
	return f != nil && f.Changed
}

func maybeDefaultEntropy(rootCmd *cobra.Command, args []string) []string {
	if len(args) == 0 {
		return args
	}
	if args[0] == "help" || args[0] == "completion" || args[0] == "-v" || args[0] == "--version" {
		return args
	}
	if found, _, err := rootCmd.Find(args); err == nil && found != rootCmd {
		return args
	}
	if prelimHelpChanged(args) {
		return args
	}
	return append([]string{"entropy"}, args...)
}

func Execute() {
	rootCmd := newRootCmd()
	rootCmd.SetArgs(maybeDefaultEntropy(rootCmd, os.Args[1:]))
	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}
