package cmd

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"deptree/internal/config"
	"deptree/internal/golang"
	"deptree/internal/graph"
	"deptree/internal/js"
	"deptree/internal/language"
	"deptree/internal/python"
	"deptree/internal/rust"

	"github.com/spf13/cobra"
)

func loadConfig(cmd *cobra.Command) (*config.Loaded, error) {
	changed := false
	if f := cmd.Flags().Lookup("config"); f != nil {
		changed = f.Changed
	}
	cli := config.CliFlags{
		UnwrapExports:        flagUnwrapExports,
		JsWorkspaces:         flagJsWorkspaces,
		JsTsConfigPaths:      flagJsTsConfigPaths,
		PythonExcludeConditional: flagPythonExcludeConditional,
		Only:                 flagOnly,
		Exclude:              flagExclude,
	}
	if f := cmd.Flags().Lookup("unwrap-exports"); f != nil { cli.UnwrapExportsChanged = f.Changed }
	if f := cmd.Flags().Lookup("js-workspaces"); f != nil { cli.JsWorkspacesChanged = f.Changed }
	if f := cmd.Flags().Lookup("js-tsconfig-paths"); f != nil { cli.JsTsConfigPathsChanged = f.Changed }
	if f := cmd.Flags().Lookup("python-exclude-conditional-imports"); f != nil { cli.PythonExcludeConditionalChanged = f.Changed }
	return config.Load(cfgFile, changed, cli)
