package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"

	"deptree/internal/entropy"
	"deptree/internal/graph"
	"deptree/internal/progress"

	"github.com/spf13/cobra"
)

var (
	entropyEnableGui      bool
	entropyNoBrowserOpen  bool
	entropyRenderPath     string
)

func newEntropyCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:     "entropy",
		Short:   "(default) Renders a 3d force-directed graph in the browser",
		GroupID: "visualize",
		Args:    ensureFilesExist,
		RunE:    runEntropy,
	}
	cmd.Flags().BoolVar(&entropyEnableGui, "enable-gui", false, "Enables a GUI for changing rendering settings")
	cmd.Flags().BoolVar(&entropyNoBrowserOpen, "no-browser-open", false, "Disable the automatic browser open while rendering entropy")
	cmd.Flags().StringVar(&entropyRenderPath, "render-path", "", "Sets the output path of the rendered html file")
	return cmd
}

func runEntropy(cmd *cobra.Command, args []string) error {
	files := filterFiles(args)
	if len(files) == 0 {
		return errNoValidFiles
	}
	loaded, err := loadConfig(cmd)
	if err != nil {
		return err
	}
	parser, err := inferLang(files, loaded)
	if err != nil {
		return err
	}
	entries := absPaths(files)
	bar := progress.New()
	g, err := graph.Load(entries, parser, ignorerFrom(loaded), bar)
	if err != nil {
		return err
	}
	if len(entries) == 1 {
		if g.ByAbs[entries[0]] == nil {
			return fmt.Errorf("could not find entrypoint %s", entries[0])
		}
	}
	renderPath := entropyRenderPath
	if renderPath == "" {
		renderPath = filepath.Join(os.TempDir(), "index.html")
	}
	data := entropy.Build(g, entries, entropyEnableGui)
	if err := os.WriteFile(renderPath, entropy.RenderHTML(data), 0o600); err != nil {
		return err
	}
	if entropyNoBrowserOpen {
		fmt.Println(renderPath)
		return nil
	}
	return openBrowser(renderPath)
}

func openBrowser(path string) error {
	var c *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		c = exec.Command("open", path)
	case "windows":
		c = exec.Command("rundll32", "url.dll,FileProtocolHandler", path)
	default:
		c = exec.Command("xdg-open", path)
	}
	return c.Start()
}
