package cmd

import (
	"encoding/json"
	"fmt"

	"deptree/internal/graph"
	"deptree/internal/progress"
	"deptree/internal/tree"

	"github.com/spf13/cobra"
)

var treeJSON bool

func newTreeCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:     "tree",
		Short:   "Render the dependency tree starting from the provided entrypoint",
		GroupID: "visualize",
		Args:    ensureFilesExist,
		RunE:    runTree,
	}
	cmd.Flags().BoolVar(&treeJSON, "json", false, "render the dependency tree in a machine readable json format")
	return cmd
}

func runTree(cmd *cobra.Command, args []string) error {
	files := filterFiles(args)
	if len(files) == 0 {
		return errNoValidFiles
	}
	loaded, err := loadConfig(cmd)
	if err != nil {
		return err
	}
	parser, err := inferLang(files, loaded)
	if err != nil {
		return err
	}
	entries := absPaths(files)
	bar := progress.New()
	bar.Start()
	if len(entries) != 1 {
		return fmt.Errorf("this functionality requires that only 1 entrypoint is provided, but %d where passed. Consider providing a single entrypoint to your program", len(entries))
	}
	ignorer := ignorerFrom(loaded)
	g, err := graph.Load(entries, parser, ignorer, bar)
	if err != nil {
		return err
	}
	if ignorer.IsIgnored(entries[0]) {
		return fmt.Errorf("selected entrypoint %s is explicitly ignored", entries[0])
	}
	if treeJSON {
		out := tree.JSONOutput(g, entries[0])
		b, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			return err
		}
		fmt.Println(string(b))
		return nil
	}
	rootNode, _ := tree.Build(g, entries[0])
	return runTUI(g, rootNode, entries[0], parser, ignorer)
}
