			loaded, err := loadConfig(cmd)
			if err != nil {
				return err
			}
			if !loaded.Exists {
				return errors.New("when using the `check` subcommand, a .dep-tree.yml file must be provided, you can create one sample .dep-tree.yml file executing `dep-tree config` in your terminal")
