cat > cmd/explain.go <<'EOF'
package cmd

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"

	"deptree/internal/globutil"
	"deptree/internal/graph"
	"deptree/internal/progress"

	"github.com/spf13/cobra"
)

var (
	explainOverlapLeft  bool
	explainOverlapRight bool
)

func newExplainCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:     "explain",
		Short:   "Shows all the dependencies between two parts of the code",
		GroupID: "explain",
		Args:    cobra.ExactArgs(2),
		RunE:    runExplain,
	}
	cmd.Flags().BoolVarP(&explainOverlapLeft, "overlap-left", "l", false, "When there's an overlap between the files at the left and the right, keep the ones at the left")
	cmd.Flags().BoolVarP(&explainOverlapRight, "overlap-right", "r", false, "When there's an overlap between the files at the left and the right, keep the ones at the right")
	return cmd
}

func globFiles(pattern string) ([]string, error) {
	matches, err := globutil.Glob(pattern)
	if err != nil {
		return nil, err
	}
	if len(matches) == 0 {
		return nil, fmt.Errorf("%s does not match with any existing file", pattern)
	}
	var files []string
	for _, m := range matches {
		info, err := os.Stat(m)
		if err == nil && !info.IsDir() {
			abs, err := filepath.Abs(m)
			if err != nil {
				abs = m
			}
			files = append(files, filepath.Clean(abs))
		}
	}
	return files, nil
}

func runExplain(cmd *cobra.Command, args []string) error {
	if explainOverlapLeft && explainOverlapRight {
		return errors.New("only one of --overlap-left (-l) or --overlap-right (-r) can be used at a time")
	}
	left, err := globFiles(args[0])
	if err != nil {
		return err
	}
	right, err := globFiles(args[1])
	if err != nil {
		return err
	}
	if len(left) == 0 || len(right) == 0 {
		return errNoValidFiles
	}
	// Overlap handling.
	rightSet := map[string]bool{}
	for _, f := range right {
		rightSet[f] = true
	}
	leftSet := map[string]bool{}
	for _, f := range left {
		leftSet[f] = true
	}
	if explainOverlapLeft {
		var nr []string
		for _, f := range right {
			if !leftSet[f] {
				nr = append(nr, f)
			}
		}
		right = nr
		rightSet = map[string]bool{}
		for _, f := range right {
			rightSet[f] = true
		}
	}
	if explainOverlapRight {
		var nl []string
		for _, f := range left {
			if !rightSet[f] {
				nl = append(nl, f)
			}
		}
		left = nl
		leftSet = map[string]bool{}
		for _, f := range left {
			leftSet[f] = true
		}
	}
	loaded, err := loadConfig(cmd)
	if err != nil {
		return err
	}
	parser, err := inferLang(left, loaded)
	if err != nil {
		return err
	}
	// Union of entries preserving order.
	seen := map[string]bool{}
	var entries []string
	for _, f := range append(append([]string(nil), left...), right...) {
		if !seen[f] {
			seen[f] = true
			entries = append(entries, f)
		}
	}
	g, err := graph.Load(entries, parser, ignorerFrom(loaded), progress.New())
	if err != nil {
		return err
	}
	type edge struct{ from, to string }
	var edges []edge
	for _, n := range g.Nodes {
		if !leftSet[n.AbsPath] {
			continue
		}
		for _, depAbs := range n.Dependencies {
			if !rightSet[depAbs] {
				continue
			}
			dep := g.ByAbs[depAbs]
			if dep == nil {
				continue
			}
			edges = append(edges, edge{n.DisplayPath, dep.DisplayPath})
		}
	}
	sort.Slice(edges, func(i, j int) bool {
		if edges[i].from != edges[j].from {
			return edges[i].from < edges[j].from
		}
		return edges[i].to < edges[j].to
	})
	for _, e := range edges {
		fmt.Printf("%s -> %s\n", e.from, e.to)
	}
	return nil
}
EOF
