import (
	"strings"

	"deptree/internal/graph"
)

type Node struct {
	Graph    *graph.Node
	Children []*Node
}

func Build(g *graph.Graph, rootAbs string) (*Node, [][]string) {
	root := g.ByAbs[rootAbs]
	if root == nil {
		return nil, [][]string{}
	}
	// First pass: DFS from the root to find back edges and cycles.
	var cycles [][]string
	seenCycle := map[string]bool{}
	cyclic := map[string]bool{}
	visited := map[string]bool{}
	var stack []string
	onStack := map[string]int{}
	var dfs func(abs string)
	dfs = func(abs string) {
		visited[abs] = true
		onStack[abs] = len(stack)
		stack = append(stack, abs)
		node := g.ByAbs[abs]
		if node != nil {
			for _, dep := range node.Dependencies {
				if idx, ok := onStack[dep]; ok {
					cyclic[abs+"->"+dep] = true
					var cyc []string
					for _, a := range stack[idx:] {
						cyc = append(cyc, g.ByAbs[a].DisplayPath)
					}
					cyc = append(cyc, g.ByAbs[dep].DisplayPath)
					key := strings.Join(cyc, "\x00")
					if !seenCycle[key] {
						seenCycle[key] = true
						cycles = append(cycles, cyc)
					}
				} else if !visited[dep] {
					dfs(dep)
				}
			}
		}
		stack = stack[:len(stack)-1]
		delete(onStack, abs)
	}
	dfs(rootAbs)
	if cycles == nil {
		cycles = [][]string{}
	}
	// Second pass: unfold using only non-cyclic edges.
	var build func(n *graph.Node, ancestors map[string]bool) *Node
	build = func(n *graph.Node, ancestors map[string]bool) *Node {
		out := &Node{Graph: n}
		for _, depAbs := range n.Dependencies {
			if cyclic[n.AbsPath+"->"+depAbs] {
				continue
			}
			if ancestors[depAbs] {
				continue
			}
			child := g.ByAbs[depAbs]
			if child == nil {
				continue
			}
			next := make(map[string]bool, len(ancestors)+1)
			for k := range ancestors {
				next[k] = true
			}
			next[depAbs] = true
			out.Children = append(out.Children, build(child, next))
		}
		return out
	}
	rootNode := build(root, map[string]bool{rootAbs: true})
	return rootNode, cycles
}

func ToMap(root *Node) map[string]interface{} {
	if root == nil {
		return map[string]interface{}{}
	}
	return map[string]interface{}{root.Graph.DisplayPath: nodeValue(root)}
}

func nodeValue(n *Node) interface{} {
	if len(n.Children) == 0 {
		return nil
	}
	m := make(map[string]interface{}, len(n.Children))
	for _, c := range n.Children {
		m[c.Graph.DisplayPath] = nodeValue(c)
	}
	return m
}

type Output struct {
	Tree                 map[string]interface{} `json:"tree"`
	CircularDependencies [][]string             `json:"circularDependencies"`
	Errors               map[string][]string    `json:"errors"`
}

func JSONOutput(g *graph.Graph, rootAbs string) Output {
	rootNode, cycles := Build(g, rootAbs)
	errs := map[string][]string{}
	for _, n := range g.Nodes {
		if len(n.Errors) > 0 {
			errs[n.DisplayPath] = n.Errors
		}
	}
	return Output{Tree: ToMap(rootNode), CircularDependencies: cycles, Errors: errs}
}
EOF
