{"command":"cat > cmd/tui_render.go <<'EOF'
package cmd

import (
	"os"
	"path/filepath"
	"sort"
	"strings"

	"deptree/internal/graph"
	"deptree/internal/language"
	"deptree/internal/tree"
)

const (
	segN = 1 << iota
	segS
	segE
	segW
)

type tuiCell struct {
	r         rune
	bits      int
	sources   map[string]bool
	labelNode string
	isMarker  bool
}

type tuiLine struct {
	cells   map[int]*tuiCell
	nodeAbs string
	level   int
}

func (l *tuiLine) cell(col int) *tuiCell {
	if l.cells == nil {
		l.cells = map[int]*tuiCell{}
	}
	c, ok := l.cells[col]
	if !ok {
		c = &tuiCell{sources: map[string]bool{}}
		l.cells[col] = c
	}
	return c
}

func (l *tuiLine) addSeg(col, bits int, source string) {
	c := l.cell(col)
	c.bits |= bits
	if source != "" {
		c.sources[source] = true
	}
}

func boxRune(bits int) rune {
	switch bits {
	case segN | segS:
		return '│'
	case segE | segW:
		return '─'
	case segN | segE:
		return '└'
	case segN | segW:
		return '┘'
	case segS | segE:
		return '┌'
	case segS | segW:
		return '┐'
	case segN | segS | segE:
		return '├'
	case segN | segS | segW:
		return '┤'
	case segN | segE | segW:
		return '┴'
	case segS | segE | segW:
		return '┬'
	case segN | segS | segE | segW:
		return '┼'
	case segN:
		return '╵'
	case segS:
		return '╷'
	case segE:
		return '╴'
	case segW:
		return '╶'
	}
	return ' '
}

type tuiLayout struct {
	lines []*tuiLine
	// For drawing: direct children (original graph adjacency) per node.
	children map[string][]string
}

func buildTuiLayout(g *graph.Graph, rootAbs string) *tuiLayout {
	rootAbs = filepath.Clean(rootAbs)
	// Sorted adjacency by display path.
	sortedAdj := map[string][]string{}
	children := map[string][]string{}
	for _, n := range g.Nodes {
		deps := append([]string(nil), n.Dependencies...)
		sort.Slice(deps, func(i, j int) bool {
			di, dj := g.ByAbs[deps[i]].DisplayPath, g.ByAbs[deps[j]].DisplayPath
			if di != dj {
				return di < dj
			}
			return deps[i] < deps[j]
		})
		sortedAdj[n.AbsPath] = deps
		children[n.AbsPath] = deps
	}
	// DFS to classify cyclic (back) edges.
	cyclic := map[string]bool{}
	visited := map[string]bool{}
	onStack := map[string]bool{}
	var dfs func(abs string)
	dfs = func(abs string) {
		visited[abs] = true
		onStack[abs] = true
		for _, dep := range sortedAdj[abs] {
			if onStack[dep] {
				cyclic[abs+"->"+dep] = true
			} else if !visited[dep] {
				dfs(dep)
			}
		}
		delete(onStack, abs)
	}
	if g.ByAbs[rootAbs] != nil {
		dfs(rootAbs)
	}
	// Forward adjacency / incoming.
	fwd := map[string][]string{}
	incoming := map[string][]string{}
	for _, n := range g.Nodes {
		if !visited[n.AbsPath] {
			continue
		}
		for _, dep := range sortedAdj[n.AbsPath] {
			if cyclic[n.AbsPath+"->"+dep] {
				continue
			}
			fwd[n.AbsPath] = append(fwd[n.AbsPath], dep)
			incoming[dep] = append(incoming[dep], n.AbsPath)
		}
	}
	// Levels: longest path in the forward DAG.
	level := map[string]int{}
	var longest func(abs string) int
	longest = func(abs string) int {
		if abs == rootAbs {
			return 0
		}
		if v, ok := level[abs]; ok {
			return v
		}
		max := -1
		for _, p := range incoming[abs] {
			if !visited[p] {
				continue
			}
			if lv := longest(p); lv > max {
				max = lv
			}
		}
		level[abs] = max + 1
		return max + 1
	}
	maxLevel := 0
	for _, n := range g.Nodes {
		if !visited[n.AbsPath] {
			continue
		}
		if lv := longest(n.AbsPath); lv > maxLevel {
			maxLevel = lv
		}
	}
	level[rootAbs] = 0
	levels := make([][]string, maxLevel+1)
	if g.ByAbs[rootAbs] != nil {
		levels[0] = []string{rootAbs}
	}
	for d := 1; d <= maxLevel; d++ {
		var order []string
		seen := map[string]bool{}
		for _, parent := range levels[d-1] {
			for _, dep := range fwd[parent] {
				if level[dep] == d && !seen[dep] {
					seen[dep] = true
					order = append(order, dep)
				}
			}
		}
		// Fallback for any missed nodes at this level, sorted by display path.
		var missed []string
		for _, n := range g.Nodes {
			if visited[n.AbsPath] && level[n.AbsPath] == d && !seen[n.AbsPath] {
				missed = append(missed, n.AbsPath)
			}
		}
		sort.Slice(missed, func(i, j int) bool { return g.ByAbs[missed[i]].DisplayPath < g.ByAbs[missed[j]].DisplayPath })
		order = append(order, missed...)
		levels[d] = order
	}
	// Label starts and tracks.
	labelStart := map[string]int{rootAbs: 0}
	track := map[string]int{}
	if len(fwd[rootAbs]) > 0 {
		track[rootAbs] = 0
	}
	markerCol := make([]int, maxLevel+1)
	maxPrevLabel := 0
	for d := 1; d <= maxLevel; d++ {
		marker := maxPrevLabel + 1
		markerCol[d] = marker
		priorInternal := 0
		maxCurr := 0
		for _, abs := range levels[d] {
			ls := marker + 1 + priorInternal
			labelStart[abs] = ls
			if ls > maxCurr {
				maxCurr = ls
			}
			if len(fwd[abs]) > 0 {
				track[abs] = ls
				priorInternal++
			}
		}
		maxPrevLabel = maxCurr
	}
	// Build ordered row list.
	type rowSpec struct {
		node string // "" => connector
		lvl  int
	}
	var specs []rowSpec
	for d := 0; d <= maxLevel; d++ {
		for _, abs := range levels[d] {
			specs = append(specs, rowSpec{node: abs, lvl: d})
		}
		if d < maxLevel {
			specs = append(specs, rowSpec{node: "", lvl: d})
		}
	}
	rowIndex := map[string]int{}
	lines := make([]*tuiLine, len(specs))
	for i, sp := range specs {
		lines[i] = &tuiLine{cells: map[int]*tuiCell{}, nodeAbs: sp.node, level: sp.lvl}
		if sp.node != "" {
			rowIndex[sp.node] = i
		}
	}
	// Last target row per source (forward edges).
	lastTarget := map[string]int{}
	for src, deps := range fwd {
		for _, dep := range deps {
			if ri, ok := rowIndex[dep]; ok && ri > lastTarget[src] {
				lastTarget[src] = ri
			}
		}
	}
	// Connector rows and node rows: vertical active tracks.
	for ri, sp := range specs {
		line := lines[ri]
		// Active vertical tracks.
		for src, tcol := range track {
			srow, ok := rowIndex[src]
			if !ok || srow >= ri {
				continue
			}
			if lastTarget[src] < ri {
				continue
			}
			bits := segN
			if lastTarget[src] > ri {
				bits |= segS
			}
			line.addSeg(tcol, bits, src)
		}
		if sp.node == "" || sp.lvl == 0 {
			continue
		}
		nodeAbs := sp.node
		d := sp.lvl
		marker := markerCol[d]
		parents := append([]string(nil), incoming[nodeAbs]...)
		// Sort parents by row index.
		sort.Slice(parents, func(i, j int) bool { return rowIndex[parents[i]] < rowIndex[parents[j]] })
		// Primary parent: first parent at level d-1 by row order.
		primary := ""
		for _, p := range parents {
			if level[p] == d-1 {
				primary = p
				break
			}
		}
		if primary == "" && len(parents) > 0 {
			// Highest level, then earliest row.
			best := -1
			for _, p := range parents {
				if level[p] > best {
					best = level[p]
					primary = p
				}
			}
		}
		parentSet := map[string]bool{}
		for _, p := range parents {
			parentSet[p] = true
		}
		// If a secondary parent lies left of the primary, the primary's north
		// segment on this row is absorbed into the horizontal line.
		skipPrimaryNorth := false
		if primary != "" {
			for _, p := range parents {
				if p != primary && track[p] < track[primary] {
					skipPrimaryNorth = true
				}
			}
		}
		if skipPrimaryNorth {
			if c, ok := line.cells[track[primary]]; ok {
				c.bits &^= segN
			}
		}
		// Horizontal segments from each parent to the marker.
		for _, p := range parents {
			tp, ok := track[p]
			if !ok {
				continue
			}
			for col := tp; col < marker; col++ {
				// Skip columns occupied by a non-parent active track.
				blocked := false
				if col != tp {
					for src, tc := range track {
						if tc == col && rowIndex[src] < ri && lastTarget[src] >= ri && !parentSet[src] {
							blocked = true
							break
						}
					}
				}
				if blocked {
					continue
				}
				bits := segE
				if col > tp {
					bits |= segW
				}
				line.addSeg(col, bits, p)
			}
		}
		// Marker cell.
		mc := line.cell(marker)
		mc.r = '▷'
		mc.isMarker = true
		mc.bits = 0
		for _, p := range parents {
			mc.sources[p] = true
		}
	}
	// Write labels.
	labelEnd := map[string]int{}
	for ri, sp := range specs {
		if sp.node == "" {
			continue
		}
		node := g.ByAbs[sp.node]
		if node == nil {
			continue
		}
		start := labelStart[sp.node]
		runes := []rune(node.DisplayPath)
		labelEnd[sp.node] = start + len(runes)
		for k, r := range runes {
			c := lines[ri].cell(start + k)
			c.r = r
			c.labelNode = sp.node
			c.bits = 0
			c.isMarker = false
		}
		_ = ri
	}
	// Back (cyclic) edges routed on the right.
	type backEdge struct{ from, to string }
	var backs []backEdge
	for _, n := range g.Nodes {
		if !visited[n.AbsPath] {
			continue
		}
		for _, dep := range sortedAdj[n.AbsPath] {
			if cyclic[n.AbsPath+"->"+dep] {
				backs = append(backs, backEdge{n.AbsPath, dep})
			}
		}
	}
	// Order back edges by source row then target row.
	sort.Slice(backs, func(i, j int) bool {
		if rowIndex[backs[i].from] != rowIndex[backs[j].from] {
			return rowIndex[backs[i].from] < rowIndex[backs[j].from]
		}
		return rowIndex[backs[i].to] < rowIndex[backs[j].to]
	})
	type interval struct{ r1, r2, col int }
	var used []interval
	for _, be := range backs {
		rFrom, rTo := rowIndex[be.from], rowIndex[be.to]
		lo, hi := rTo, rFrom
		if lo > hi {
			lo, hi = hi, lo
		}
		col := labelEnd[be.from]
		if labelEnd[be.to] > col {
			col = labelEnd[be.to]
		}
		for r := lo; r <= hi; r++ {
			if specs[r].node != "" {
				if e := labelEnd[specs[r].node]; e > col {
					col = e
				}
			}
		}
		// Avoid overlapping another back-track on shared rows.
		for {
			conflict := false
			for _, u := range used {
				if u.col == col && lo <= u.r2 && u.r1 <= hi {
					conflict = true
					break
				}
			}
			if !conflict {
				break
			}
			col++
		}
		used = append(used, interval{lo, hi, col})
		// Target row: '◁' at label end, dashes to col, corner.
		te := labelEnd[be.to]
		tc := lines[rTo].cell(te)
		tc.r = '◁'
		tc.bits = 0
		tc.labelNode = ""
		tc.sources[be.from] = true
		for c := te + 1; c < col; c++ {
			cc := lines[rTo].cell(c)
			cc.r = '─'
			cc.bits = 0
			cc.sources[be.from] = true
		}
		if col > te {
			cc := lines[rTo].cell(col)
			cc.r = '┐'
			cc.bits = 0
			cc.sources[be.from] = true
		}
		// Source row: dashes from label end to col, corner.
		se := labelEnd[be.from]
		for c := se; c < col; c++ {
			cc := lines[rFrom].cell(c)
			cc.r = '─'
			cc.bits = 0
			cc.sources[be.from] = true
		}
		sc := lines[rFrom].cell(col)
		sc.r = '┘'
		sc.bits = 0
		sc.sources[be.from] = true
		// Intermediate rows.
		for r := lo + 1; r < hi; r++ {
			cc := lines[r].cell(col)
			cc.r = '│'
			cc.bits = 0
			cc.sources[be.from] = true
		}
	}
	// Materialise box runes for segment cells without an explicit rune.
	for _, line := range lines {
		for _, c := range line.cells {
			if c.r == 0 && c.bits != 0 {
				c.r = boxRune(c.bits)
			}
		}
	}
	return &tuiLayout{lines: lines, children: children}
}

// tuiRun is defined in tui_loop.go via tuiLoop delegating here (see below).
var _ = strings.TrimSpace
var _ = os.Getenv
var _ language.Parser
var _ = tree.Build
EOF
gofmt -w cmd/tui_render.go"}

