func tuiLoop(tty *os.File, g *graph.Graph, root *tree.Node, rootAbs string, parser language.Parser, ignorer *graph.Ignorer) error {
	type viewState struct {
		rootAbs  string
		selected int
		scroll   int
	}
	var stack []viewState
	currentRoot := rootAbs
	layout := buildTuiLayout(g, currentRoot)
	selected := 0
	scroll := 0
	help := false

	draw := func() {
		cols, rows := tuiWindowSize(tty)
		if rows <= 0 {
			rows = 24
		}
		if cols <= 0 {
			cols = 80
		}
		var b strings.Builder
		b.WriteString("\x1b[H")
		if help {
			lines := strings.Split(strings.TrimSuffix(helpText(), "\n"), "\n")
			for r := 0; r < rows; r++ {
				if r < len(lines) {
