				}
				b.WriteString("\x1b[K")
				if r < rows-1 {
					b.WriteString("\r\n")
				}
			}
			tty.WriteString(b.String())
			return
		}
		// Keep selection visible.
		if selected < scroll {
			scroll = selected
		}
		if selected >= scroll+rows {
			scroll = selected - rows + 1
		}
		if scroll < 0 {
			scroll = 0
		}
		// Selected node abs (if the selected line is a node row).
		selectedAbs := ""
		if selected >= 0 && selected < len(layout.lines) {
			selectedAbs = layout.lines[selected].nodeAbs
		}
		childSet := map[string]bool{}
		if selectedAbs != "" {
			for _, c := range layout.children[selectedAbs] {
				childSet[c] = true
			}
		}
		for r := 0; r < rows; r++ {
			idx := scroll + r
			if idx < len(layout.lines) {
				b.WriteString(renderTuiLine(layout.lines[idx], selectedAbs, childSet, cols))
			}
			b.WriteString("\x1b[K")
			if r < rows-1 {
				b.WriteString("\r\n")
			}
		}
		tty.WriteString(b.String())
	}

	// Input goroutine.
	type inputEvent struct {
		data []byte
		err  error
	}
	events := make(chan inputEvent, 4)
	go func() {
		buf := make([]byte, 64)
		for {
			n, err := tty.Read(buf)
			if n > 0 {
				cp := append([]byte(nil), buf[:n]...)
				events <- inputEvent{data: cp}
			}
			if err != nil {
				events <- inputEvent{err: err}
				return
			}
		}
	}()
	resize := make(chan os.Signal, 2)
	signal.Notify(resize, syscall.SIGWINCH)
	defer signal.Stop(resize)

	draw()
	for {
		select {
		case <-resize:
			draw()
			continue
		case ev := <-events:
			if ev.err != nil {
				return ev.err
			}
			quit := false
			for _, by := range ev.data {
				if help {
					if by == 'q' {
						help = false
					}
					continue
				}
				_, rows := tuiWindowSize(tty)
				if rows <= 0 {
					rows = 24
				}
				switch by {
				case 'q':
					if len(stack) > 0 {
						prev := stack[len(stack)-1]
						stack = stack[:len(stack)-1]
						currentRoot = prev.rootAbs
						layout = buildTuiLayout(g, currentRoot)
						selected = prev.selected
						scroll = prev.scroll
					} else {
						quit = true
					}
				case 'h':
					help = true
				case 'j':
					if selected < len(layout.lines)-1 {
						selected++
					}
				case 'k':
					if selected > 0 {
						selected--
					}
				case 4: // Ctrl-D
					selected += rows / 2
					if selected > len(layout.lines)-1 {
						selected = len(layout.lines) - 1
					}
					if selected < 0 {
