					break
				}
			}
			if quit {
				return nil
			}
			draw()
		}
	}
}

func renderTuiLine(line *tuiLine, selectedAbs string, childSet map[string]bool, cols int) string {
	if len(line.cells) == 0 {
		return ""
	}
	maxCol := 0
	for c := range line.cells {
		if c > maxCol {
			maxCol = c
		}
	}
	var b strings.Builder
	curStyle := 0 // 0 default, 32 green, 36 cyan
	setStyle := func(s int) {
		if s == curStyle {
			return
		}
		if s == 0 {
			b.WriteString("\x1b[39m")
		} else {
			b.WriteString("\x1b[")
			b.WriteString(strings.TrimSpace(strings.Replace(strings.Trim(strings.Repeat(" ", 0), " "), " ", "", -1))) // no-op keeper
			// Emit colour code.
			b.WriteString(colorCode(s))
			b.WriteString("m")
		}
		curStyle = s
	}
	for col := 0; col <= maxCol && col < cols; col++ {
		c, ok := line.cells[col]
		if !ok || c.r == 0 {
			setStyle(0)
			b.WriteRune(' ')
			continue
		}
		style := 0
		if c.labelNode != "" {
			if selectedAbs != "" && c.labelNode == selectedAbs {
				style = 32
			} else if selectedAbs != "" && childSet[c.labelNode] {
				style = 36
			}
		} else if selectedAbs != "" && c.sources[selectedAbs] {
			style = 32
		}
		setStyle(style)
		b.WriteRune(c.r)
	}
	if curStyle != 0 {
		b.WriteString("\x1b[39m")
	}
	return b.String()
}

func colorCode(s int) string {
	if s == 32 {
		return "32"
	}
	return "36"
}
