		return out
	}
	srcTrack, ok := layout.trackByNode[selectedAbs]
	if !ok {
		return out
	}
	srcRow := layout.rowByNode[selectedAbs]
	set := func(row, col int, r rune) {
		if out[row] == nil {
			out[row] = map[int]rune{}
		}
		out[row][col] = r
	}
	maxChildRow := srcRow
	for _, ch := range children {
