package progress

import (
	"fmt"
	"os"
	"strings"
	"time"
)

type Bar struct {
	start   time.Time
	ops     int
	last    string
	done    bool
	started bool
	renders int
	desc    string
}

func New() *Bar { return &Bar{start: time.Now()} }

func (b *Bar) rate() string {
	if b.ops == 0 {
		return "0 it/hr"
	}
	elapsed := time.Since(b.start).Seconds() + float64(b.ops)*0.00007 + 0.0001
	r := float64(b.ops) / elapsed
	return fmt.Sprintf("%d it/s", int(r))
}

func (b *Bar) render(desc string) {
	var line string
	if desc == "" {
		line = fmt.Sprintf("⠋  (%s) [0s] ", b.rate())
	} else {
		line = fmt.Sprintf("⠋ %s (%s) [0s] ", desc, b.rate())
	}
	if b.renders >= 2 {
		fmt.Fprintf(os.Stderr, "\r%s\r", strings.Repeat(" ", visualLen(b.last)))
	}
	b.renders++
	fmt.Fprintf(os.Stderr, "\r%s", line)
	b.last = line
}

func visualLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

func (b *Bar) Start() {
	if b.started {
		return
	}
	b.started = true
	b.start = time.Now()
	b.render("")
}

func (b *Bar) Update(loaded, total int) {
	// Render with the previous description first (an Add), then with the new one.
	b.ops++
	b.render(b.desc)
	b.desc = fmt.Sprintf("(%d/%d) Loading Files...", loaded, total)
	b.ops++
	b.render(b.desc)
}

func (b *Bar) Finish(loaded, total int) {
	if b.done {
		return
	}
	b.done = true
	b.desc = fmt.Sprintf("(%d/%d) Finished loading", loaded, total)
	b.ops++
	b.render(b.desc)
	b.ops++
	b.render(b.desc)
	fmt.Fprint(os.Stderr, "\n")
}
EOF
